(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0002.js"] = [{"id":"poem-0d028c9636c94fd3e01d1cea","title":"初渡淮北岸","author":"杨凝","dynasty":"唐","verses":["别梦虽难觉，悲魂最易销。","慇勤淮北岸，乡近去家遥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d60a1c3d-f288-4adb-a73f-baab5e6bf0a3","tags":[]},{"id":"poem-0d05192913da2b89f4dcc7b1","title":"玉楼春·尊前拟把归期说","author":"欧阳修","dynasty":"宋","verses":["尊前拟把归期说。","未语春容先惨咽。","人生自是有情痴，此恨不关风与月。","离歌且莫翻新阕。","一曲能教肠寸结。","直须看尽洛城花，始共春风容易别。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-669","tags":[]},{"id":"poem-0d0ba9c592d2b38c506c5291","title":"淳熙四年二月既望静江守臣张某奉诏劝农于郊乃作熙熙阳春之诗二十四章章四句以示父老俾告于其乡之人而歌之  其二三","author":"张栻","dynasty":"宋","verses":["咨尔父老，尚演厥义。","其讽其歌，于乡于里。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-bcf59d8a-5636-48f0-bb87-94405bc0e19a","tags":[]},{"id":"poem-0d19d824f6a68ed16e6b6382","title":"卜算子·一叶鉴中来","author":"魏杞","dynasty":"宋","verses":["一叶鉴中来，两岸青山起。","送我红蕖万柄香，疑在蓬壶里。","天地莹无尘，巾袂凉如水。","白浪无声月自高，不是人间世。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-546","tags":[]},{"id":"poem-0d1ef3be273a6cc1bdbca4f3","title":"赠卫南长官赴任","author":"李嘉祐","dynasty":"唐","verses":["吏曹难茂宰，主意念疲人。","更事文犀节，还过白马津。","云间辞北阙，树里出西秦。","为报陶明府，裁书莫厌贫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3fb130fc-fd7a-4f7a-9128-120886ff520b","tags":[]},{"id":"poem-0d21c1cb3405c9da68218920","title":"太湖馆送殷秀才赴举","author":"皎然","dynasty":"唐","verses":["春风洞庭路，摇荡暮天多。","衰疾见芳草，别离伤远波。","诗名推首荐，赋甲拟前科。","数日闻天府，山衣制芰荷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1439bee2-2d1c-48b2-82c3-b404a9fdacbc","tags":["太湖","洞庭湖"]},{"id":"poem-0d236d12c535c9c2bdd5a48e","title":"酹江月","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["玉楼绛气，卷霞绡云浪寒光澄澈。","丹桂飘香清思爽，人在瑶台银阙。","(生)影透空帏，光窥罗帐，露冷蛩声切。","关山今夜，照人几处离别。","(净)须信离合悲欢，还如玉兔，有阴晴圆缺。","便做人生长宴会，几见冰轮皎洁？(丑)此夜明多，隔生期远，莫放金樽歇。","(合)但愿人长久，年年同赏明月。","(贴唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5152","tags":[]},{"id":"poem-0d23ca9d9474cf62db06a89c","title":"横吹曲辞 折杨柳","author":"翁绶","dynasty":"唐","verses":["紫陌金堤映绮罗，游人处处动离歌。","阴移古戍迷荒草，花带残阳落远波。","台上少年吹白雪，楼中思妇敛青蛾。","殷勤攀折赠行客，此去关山雨雪多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-32744451-b4f4-47d1-866c-44b2675377c3","tags":[]},{"id":"poem-0d336ecd15d09c8146f8b1de","title":"春山三朅来 一","author":"李涉","dynasty":"唐","verses":["钓鱼朅来春日暖，沿溪不厌舟行缓。","野竹初栽碧玉长，澄潭欲下青丝短。","昔人避世兼避讐，暮栖云外朝悠悠。","我今无事亦如此，赤鲤忽到长竿头。","泛泛随波凡几里，碧莎如烟沙似砥。","瘦壁横空怪石危，山花鬬日禽争水。","有时带月归扣舷，身闲自是渔家仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2492153c-d2ed-4dae-a398-248f53e1c711","tags":[]},{"id":"poem-0d4b23d2ec10aef22c3f3e41","title":"断火谣","author":"苏拯","dynasty":"唐","verses":["谁谓之推贤，于世何功果。","绝尔晋侯交，禁我唐虞火。","国闭檀榆烟，大礼成隳堕。","暗室枯槁饭，冷面相看坐。","阳升既非佑，阴伏若为佐。","焉冻群生腹，将止天下祸。","但究冤滥刑，天道无不可。","鄙哉前朝翊赞臣，𬣙谟之规何琐琐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9b4fe8ad-ec28-4e02-b811-6d0be1debfe4","tags":[]},{"id":"poem-0d4bcc26adf3052b08c8d6e1","title":"山居八咏 二","author":"常达","dynasty":"唐","verses":["晚望虚庭物，心心见祖情。","烟开分岳色，雨雾减泉声。","远树猨长啸，层岩日乍明。","更堪论的意，林下笋新生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6a6228ce-2dcc-4e4d-acc3-652b3a417bfa","tags":[]},{"id":"poem-0d520b1c93a73de6d19445d4","title":"兵要望江南 《周易》占候第二十六（三十七首） 二十六","author":"易静","dynasty":"唐","verses":["官临火，尅我应（辛本、川本作「虑」）偷营。","水立官乡休立寨，土临官鬼四方兵，不可（辛本、川本作「一」）乱提兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-70518158-d441-49fa-8a13-745a6dbb5a39","tags":[]},{"id":"poem-0d5768bc545ea1a6b25f77be","title":"和刁推官蓼花二首  其二","author":"苏颂","dynasty":"宋","verses":["莲疏菊未破，野艳独敷荣。","濯水红缨细，铺园步障平。","露寒偏发色，风劲不摧茎。","采掇聊供饵，丹房助气清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-e264209b-a264-46a0-add9-94d9bfe0063a","tags":[]},{"id":"poem-0d580cd361242262b0391262","title":"浪淘沙·万恨苦绵绵","author":"欧阳修","dynasty":"宋","verses":["万恨苦绵绵。","旧约前欢。","桃花溪畔柳阴间。","几度日高春垂重，绣户深关。","楼外夕阳闲。","独自凭阑。","一重水隔一重山。","水阔山高人不见，有泪无言。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-729","tags":[]},{"id":"poem-0d5a03523a9b617061a26acc","title":"朱槿花","author":"李绅","dynasty":"唐","verses":["瘴烟长暖无霜雪，槿艳繁花满树红。","每叹芳菲四时厌，不知开落有春风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fbcb2a21-ed3f-47ab-9efa-d02004995e1e","tags":[]},{"id":"poem-0d6b69f903afc56e49497dea","title":"梁州令","author":"萧德祥《小孙屠》","dynasty":"元","verses":["一对鸾凰共宴乐。","恨连日抛弹。","这冤家莫竟信刁唆，把奴家，恩和爱，尽奚落。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8611","tags":[]},{"id":"poem-0d777f65a535cf59319ce63f","title":"冯双礼珠弹云璈以答歌","author":"李翔","dynasty":"唐","verses":["王母词终荐碧桃，答歌仙子奏云璈。","调凌空洞音初起，曲丽钧天韵更高。","霞断已翔烟际鹤，风生欲抃海心鳌。","瑶池侍女争回首，无隈琅英坠节毛。","（项云「无隈」当作「无限」，形近而误。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6296651d-15d5-4f47-bb90-6cf2b1b14e62","tags":[]},{"id":"poem-0d77b449eb44f26b3929b05b","title":"赠长安小主人","author":"李涉","dynasty":"唐","verses":["上清真子玉童颜，花态娇羞月思闲。","仙路迷人应有术，桃源不必在深山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d15a28d4-a1c4-4cdf-a3b3-0108e89eb5c5","tags":[]},{"id":"poem-0d8608e028191eccfbdbf360","title":"郊庙歌辞 享太庙乐章 保大舞","author":"郭子仪","dynasty":"唐","verses":["於穆文考，圣神昭章。","肃勺群慝，含光远方。","万物茂遂，九夷宾王。","愔愔云韶，德音不忘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-1700afdb-215f-4a06-b555-c4b3fb9e9375","tags":[]},{"id":"poem-0d8d48126a099eee1e68b4bc","title":"送缙云苗太守","author":"王维","dynasty":"唐","verses":["手疏谢明主，腰章为长吏。","方从会稽邸，更发汝南骑。","按节下松阳，清江响铙吹。","露冕见三吴，方知百城贵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-80997560-77bc-4730-b79d-2327a02f088a","tags":[]},{"id":"poem-0da282e948a034a27a7911de","title":"如梦令·罗袜半钩新月","author":"史浩","dynasty":"宋","verses":["罗袜半钩新月。","更把凤鞋珠结。","步步著金莲，行得轻轻瞥瞥。","难说。","难说。","真是世间奇绝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-170","tags":[]},{"id":"poem-0da9e88ca41d58e17300d0ef","title":"四牡","author":"佚名","dynasty":"先秦","verses":["四牡𬴂𬴂，周道倭迟。岂不怀归？王事靡盬，我心伤悲。","四牡𬴂𬴂，啴啴骆马。岂不怀归？王事靡盬，不遑启处。","翩翩者鵻，载飞载下，集于苞栩。王事靡盬，不遑将父。","翩翩者鵻，载飞载止，集于苞杞。王事靡盬，不遑将母。","驾彼四骆，载骤骎骎。岂不怀归？是用作歌，将母来谂。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-161","tags":[]},{"id":"poem-0daa20b2bd0dbedbccdbd60d","title":"离别难·宝马晓鞲雕鞍","author":"薛昭蕴","dynasty":"五代","verses":["宝马晓鞲雕鞍，罗帷乍别情难。","那堪春景媚，送君千万里。","半妆珠翠落，露华寒。","红蜡烛，青丝曲，偏能钩引泪阑干。","良夜促，香尘绿，魂欲迷，檀眉半敛愁低。","未别心先咽，欲语情难说。","出芳草，路东西。","摇袖立，春风急，樱花杨柳雨凄凄。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-39","tags":[]},{"id":"poem-0dab0d46892208478348b921","title":"笔","author":"米芾","dynasty":"宋","verses":["摹画由来妙手知，彩笺落处直疑飞。","寸心用尽终何补，赢得霜毫秃后归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-3afe8ff3-96b5-44f7-9b93-5bb12552f8eb","tags":[]},{"id":"poem-0db98a712e81da81d26aad0b","title":"好姐姐","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["指望终身奉养，谁知道中途肮脏。","存亡未审，使奴愁断肠，心凄怆。","奴家烧此夜香呵，愿得亲姑早会无灾障，骨肉团圆乐最长。","想我丈夫有了奴家呵，。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8281","tags":[]},{"id":"poem-0dba09880d215e58f8ee1837","title":"旅行","author":"孟郊","dynasty":"唐","verses":["楚水结冰薄，楚云为雨微。","野梅参差发，旅榜逍遥归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-38745ddb-3c6b-429d-b0d4-d89824c3d6a4","tags":[]},{"id":"poem-0dbbe2d8f9abf602896b81ed","title":"郊庙歌辞 武后大享昊天乐章 十二","author":"不详","dynasty":"唐","verses":["式干路，辟天扉。","回日驭，动云衣。","登金阙，入紫微。","望仙驾，仰恩徽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-97918258-9ba8-4799-b271-650864515192","tags":[]},{"id":"poem-0dbe4555c7c4beceb082d5fb","title":"北邙行","author":"张籍","dynasty":"唐","verses":["洛阳北门北邙道，丧车辚辚入秋草。","车前齐唱薤露歌，高坟新起白峨峨。","朝朝暮暮人送葬，洛阳城中人更多。","千金立碑高百尺，终作谁家柱下石。","山头松柏半无主，地下白骨多于土。","寒食家家送纸钱，乌鸢作窠衔上树。","人居朝市未解愁，请君暂向北邙游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3f1aa35f-ea49-46f3-9a38-cd901e54bd88","tags":[]},{"id":"poem-0dc4aa560438ac0b505f19e7","title":"四月","author":"佚名","dynasty":"先秦","verses":["四月维夏，六月徂署。先祖匪人，胡宁忍予？","秋日凄凄，百卉具腓。乱离瘼矣，爰其适归？","冬日烈烈，飘风发发。民莫不谷，我独何害？","山有嘉卉，侯栗侯梅。废为残贼，莫知其尤！","相彼泉水，载清载浊。我日构祸，曷云能谷？","滔滔江汉，南国之纪。尽瘁以仕，宁莫我有？","匪鹑匪鸢，翰飞戾天。匪鳣匪鲔，潜逃于渊。","山有蕨薇，隰有杞桋。君子作歌，维以告哀。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-203","tags":[]},{"id":"poem-0dc7d3281f77fe5bf84a5fe9","title":"陈晞颜董漕湖南过零陵用简斋韵见赠次韵谢之又赋一篇述怀  其一","author":"曾协","dynasty":"宋","verses":["笔到钟王意有余，诗章高古过黄初。","班行未上论思地，远使聊宣宽大书。","乞与丰年均饱煖，更申严令绝侵渔。","肯迂使节存支郡，咫尺犹嫌会面疎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-ac6f1f74-d0c2-4dcd-842e-4d38579d1143","tags":[]},{"id":"poem-0dd2b66168a1993f2bc21b0e","title":"江行无题一百首 七十九","author":"钱珝","dynasty":"唐","verses":["光阔重湖水，低斜远鴈行。","未曾无兴咏，多谢沈东阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-0fa43a5f-9cdd-4b61-83ff-e789b5bde426","tags":[]},{"id":"poem-0ddd4a9b","title":"所见","author":"袁枚","dynasty":"清","verses":["牧童骑黄牛，歌声振林樾。","意欲捕鸣蝉，忽然闭口立。"],"enabled":true,"collection":"历代名篇","source":"袁枚《小仓山房诗集》诗《所见》。","tags":["童趣"]},{"id":"poem-0de10d3d41dbacba153cd18a","title":"端州江亭得家书二首 一","author":"李绅","dynasty":"唐","verses":["雨中鹊语喧江树，风处蛛丝飏水浔。","开拆远书何事喜，数行家信抵千金。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-28f3b894-be4e-49b4-9e95-fb1550e10750","tags":[]},{"id":"poem-0de3e0c18712853c03a323ee","title":"梦游天姥吟留别","author":"李白","dynasty":"唐","verses":["海客谈瀛洲，烟涛微茫信难求。","越人语天姥，云霓明灭或可覩。","天姥连天向天横，势拔五岳掩赤城。","天台四万八千丈，对此欲倒东南倾。","我欲因之梦吴越，一夜飞度镜湖月。","湖月照我影，送我至剡溪。","谢公宿处今尚在，渌水荡漾清猨啼。","脚著谢公屐，身登青云梯。","半壁见海日，空中闻天鸡。","千岩万转路不定，迷花倚石忽已暝。","熊咆龙吟殷岩泉，栗深林兮惊层巅。","云青青兮欲雨，水澹澹兮生烟。","列缺霹雳，丘峦崩摧。","洞天石扇，訇然中开。","青冥浩荡不见底，日月照耀金银台。","霓为衣兮风为马，云之君兮纷纷而来下。","虎鼓瑟兮鸾回车，仙之人兮列如麻。","忽魂悸以魄动，怳惊起而长嗟。","惟觉时之枕席，失向来之烟霞。","世间行乐亦如此，古来万事东流水。","别君去时何时还，且放白鹿青崖间，须行即骑访名山。","安能摧眉折腰事权贵？使我不得开心颜。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-606d0bd8-31d2-4a7a-97ee-341956e7be60","tags":["唐诗三百首","一年级下册","七言古诗","高中古诗","记梦","古体"]},{"id":"poem-0de74a756de2ee1822cd83c3","title":"燕歌行","author":"高适","dynasty":"唐","verses":["汉家烟尘在东北，汉将辞家破残贼。","男儿本自重横行，天子非常赐颜色。","𪭢金伐鼓下榆关，旌斾逶迤碣石间。","校尉羽书飞瀚海，单于猎火照狼山。","山川萧条极边土，胡骑凭陵杂风雨。","战士军前半死生，美人帐下犹歌舞。","大漠穷秋塞草腓，孤城落日鬬兵稀。","身当恩遇恒轻敌，力尽关山未解围。","铁衣远戍辛勤久，玉筯应啼别离后。","少妇城南欲断肠，征人蓟北空回首。","边庭飘飖那可度，绝域苍茫更何有。","杀气三时作阵云，寒声一夜传刁斗。","相看白刃血纷纷，死节从来岂顾勋。","君不见沙场征战苦，至今犹忆李将军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e34f74b5-69ff-4136-927a-80d42eaeef6d","tags":[]},{"id":"poem-0de9a4f472dcbb587e37f3b9","title":"和杨明府早秋游法华寺","author":"皎然","dynasty":"唐","verses":["释事出县合，初闻兹山灵。","寺扉隐天色，影刹遥丁丁。","碧峰委合沓，香蔓垂蓂苓。","清景为公有，放旷云边亭。","秋赏石潭洁，夜嘉杉月清。","诵空性不昧，助道迹又经。","是以于物理，纷然若未形。","移来字人要，全与此道冥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-058af41c-0711-4f11-9a5a-c3e9f19a4df9","tags":[]},{"id":"poem-0df3b2e9cae51dc1d524cbe9","title":"我行其野","author":"佚名","dynasty":"先秦","verses":["我行其野，蔽芾其樗。婚姻之故，言就尔居。尔不我畜，复我邦家。","我行其野，言采其蓫。婚姻之故，言就尔宿。尔不我畜，言归斯复。","我行其野，言采其葍。不思旧姻，求尔新特。成不以富，亦祗以异。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-187","tags":[]},{"id":"poem-0df88eba6d3f2359b1ab336b","title":"郊庙歌辞 朝日乐章 舒和","author":"不详","dynasty":"唐","verses":["崇牙树羽延调露，旋宫扣律掩承云。","诞敷懿德昭神武，载集丰功表睿文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6db72031-e135-4ad6-a385-1c7ab06cd6db","tags":[]},{"id":"poem-0e01be001ec6b84b24ff990f","title":"菩萨蛮 其十三","author":"温庭筠","dynasty":"唐","verses":["雨暗夜合玲珑日，万枝香袅红丝拂。","闲梦忆金堂，满庭萱草长。","绣帘垂簏簌，眉黛远山绿。","春水渡溪桥，凭栏魂欲消。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-12","tags":[]},{"id":"poem-0e02d8e5caa37dad977d8289","title":"句（《吟窗杂录》卷三一《历代吟谱》引此二句，题作《秋夕诗》。）","author":"卞震","dynasty":"唐","verses":["空囊万里客，斜月一床寒。","（见《宋诗纪事》引宋失名撰《历代吟谱》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3a8e3553-61d2-479e-ab2a-28e76b1852a6","tags":[]},{"id":"poem-0e12e82a6b8b13cc59365a29","title":"蝶恋花·欲减罗衣寒未去","author":"赵令","dynasty":"宋","verses":["欲减罗衣寒未去。","不卷珠帘，人在深深处。","红杏枝头花几许。","啼痕止恨清明雨。","尽日沈烟香一缕。","宿酒醒迟，恼破春情绪。","飞燕又将归信误。","小屏风上西江路。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-72","tags":["宋词三百首"]},{"id":"poem-0e15fd9ddf07e8d3861e6c5b","title":"送鴈","author":"虚中","dynasty":"唐","verses":["云梦[千]（午）（从《诗学指南》本改）行去，潇湘一夜空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-9d01c9b5-603e-47c1-8abf-e03fff5b6732","tags":[]},{"id":"poem-0e2344993e6faca49c5ac0eb","title":"枫桥夜泊","author":"张继","dynasty":"唐","verses":["月落乌啼霜满天，江枫渔父对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3cda5a92-ffa2-4af0-9217-97ce36113705","tags":["唐诗三百首","写景","秋天","七言绝句","思乡","秋"]},{"id":"poem-0e256761d2358bda28966acb","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 五","author":"易静","dynasty":"唐","verses":["占宿次，今夜定如何。","太乙天罡太冲上，支干见者恐奔过（京本作「波」），准（辛本、川本、京本作「整」）备御兵戈（京本作「预防他」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-03135240-a4ea-440c-87bd-787b6841ad98","tags":[]},{"id":"poem-0e2573e93e87ac16b01ef81a","title":"奉和圣制天长节赐宰臣歌应制","author":"王维","dynasty":"唐","verses":["太阳升兮照万方，开阊阖兮临玉堂。","俨冕旒兮垂衣裳，金天净兮丽三光。","彤庭曙兮延八荒，德合天兮礼神徧。","灵芝生兮庆云见，唐尧后兮稷卨臣。","匝宇宙兮华胥人，尽九服兮皆四邻，干降瑞兮坤降珍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-9c86dd14-c343-4536-9713-93ac4edbbf8e","tags":[]},{"id":"poem-0e25ce3e9c515f402af6b456","title":"程帅以诗见慰用韵谢之","author":"陈造","dynasty":"宋","verses":["平时联辉星，转首食既月。","谁能玄览空，影事睨盈缺。","老子一掬泪，未憗谢天合。","生世岐高下，末路各一穴。","庄生悟浮休，荀粲枉悲咽。","公言敬书绅，闻道有先达。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-874c711c-a5b3-4dbb-9291-5b8aa2123b87","tags":[]},{"id":"poem-0e30b24269c6499facbbae4f","title":"送远上人","author":"李洞","dynasty":"唐","verses":["海岳两无边，去来都偶然。","齿因吟后冷，心向静中圆。","虫网花间井，鸿鸣雨后天。","叶书归旧寺，应附载钟船。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4aa267cd-08ab-419b-8259-a0fbbc3bcaa4","tags":[]},{"id":"poem-0e3715364cd90afda2a9fcde","title":"从宴桃花园咏桃花应制","author":"赵彦伯","dynasty":"唐","verses":["红萼竞燃春苑曙，䒠茸新吐御筵开。","长年愿奉西王䜩，近侍惭无东朔才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ab6b9019-8e9e-4c78-9b41-8870ad5c9d30","tags":[]},{"id":"poem-0e3afd1bdac0feca60c4d4f9","title":"浣溪沙·云曳香绵彩柱高","author":"欧阳修","dynasty":"宋","verses":["云曳香绵彩柱高。","绛旗风飐出花梢。","一梭红带往来抛。","束素美人羞不打，却嫌裙慢褪纤腰。","日斜深院影空摇。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-738","tags":[]},{"id":"poem-0e416745cb574ead64be6ab4","title":"送顾道士游洞庭山","author":"皎然","dynasty":"唐","verses":["见说洞庭无上路，春游乱踏五灵芝。","含桃风起花狼籍，正是仙翁碁散时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-7aff5d0b-5559-4355-a080-5054655f2f3c","tags":["洞庭湖"]},{"id":"poem-0e5c8df98f49b76190263e99","title":"虞美人·金闺平帖春云暖","author":"周邦彦","dynasty":"宋","verses":["金闺平帖春云暖。","昼漏花前短。","玉颜酒解艳红消。","一面捧心啼困、不成娇。","别来新翠迷行径。","窗锁玲珑影。","砑绫小字夜来封。","斜倚曲栏凝睇、数归鸿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-436","tags":[]},{"id":"poem-0e5c9c8db9278da4c94b0f7b","title":"诉衷情·碧沼红芳烟雨静","author":"韦庄","dynasty":"五代","verses":["碧沼红芳烟雨静，倚兰桡。","垂玉珮，交带，袅纤腰。","鸳梦隔星桥，迢迢。","越罗香暗销，坠花翘。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-17","tags":[]},{"id":"poem-0e5ca81ac9fa9b44a581c04d","title":"赠赵叟（题拟）","author":"何蒙","dynasty":"唐","verses":["桂枝轮却正凄然，又被鸎声聒昼眠。","唯有赵翁知仔细，相传好语待来年。","（见《江南余载》卷上。","）（〖1〗《江南余载》：赵叟者，自保大之初至于开宝之季，尝为贡院门子，每岁放榜之后，或去或留，率庆慰之，若出于叟手然。","进士何蒙目前叟诗曰〖诗不重录〗云云。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2631be4e-9d41-4a60-960c-12f77c7e2454","tags":[]},{"id":"poem-0e6d57cd89b6c6d80c937189","title":"送同年郑祥先辈归汉南","author":"薛逢","dynasty":"唐","verses":["年来惊喜两心知，高处同攀次第枝。","人倚绣屏闲赏夜，马嘶花径醉归时。","声名本自文章得，藩溷曾劳笔砚随。","家去恩门四千里，只应从此梦旌旗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c0d46b44-5cb0-4329-9502-3a9d0d38066e","tags":[]},{"id":"poem-0e6d631fe9fb7a358427b843","title":"答林行父","author":"宋伯仁","dynasty":"宋","verses":["男儿未肯著渔蓑，且把屠龙一剑磨。","宣室岂容无贾谊，词林尚可著廉颇。","壮怀每被愁怀恼，官况宁如旅况多。","我欲便归归未得，江南孤负采菱歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-2f0b7a80-6266-4f9f-a004-5bf37938f897","tags":[]},{"id":"poem-0e777d705e5dfdc02edf0efd","title":"晦日湖塘","author":"孙逖","dynasty":"唐","verses":["吉日初成晦，方塘遍是春。","落花迎二月，芳树历三旬。","公子能留客，巫阳好解神。","夜还何虑暗，秉烛向城𬮱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-67866d08-d669-45e3-b804-ec3192aaf75f","tags":[]},{"id":"poem-0e782ec16cccdc09a2df50e1","title":"送赵西里官满归永嘉","author":"释居简","dynasty":"宋","verses":["宣城归到西湖寺，朋旧如沙散不收。","盟鹭又随西里远，惊猿空伴北山愁。","同途好友须题品，可意佳篇便献酬。","摘得甘花烦见寄，趁它大火未西流。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d6d1868a-6dac-484d-9054-73d060cf385a","tags":["西湖"]},{"id":"poem-0e78a65de60b4f1ff0eb0d85","title":"悼诗","author":"后主煜","dynasty":"唐","verses":["永念难消释，孤怀痛自嗟。","雨深秋寂莫，愁引病增加。","咽绝风前思，昏蒙眼上花。","空王应念我，穷子正迷家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-932de3da-b56d-4987-b9cc-3b2d5956a4ff","tags":[]},{"id":"poem-0e7ba308bc6ad7ab91128f71","title":"幽居","author":"吕从庆","dynasty":"唐","verses":["茅茨何潇潇，邱园复寥廓。","黄冠此中居，眷言寄高托。","理乱无闻声，荣辱不相着。","有书聊把娱，有酒自斟酌。","侵晨课田桑，归来日华薄。","盘桓松竹间，鸟动残云落。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-572dec6b-b8c3-4c87-8026-244a64c7c647","tags":[]},{"id":"poem-0e8442a8d151cd97e27d1828","title":"再次韵答节推司理","author":"陈造","dynasty":"宋","verses":["人生行乐当及时，底用躭古仍癖诗。","老子平日汗牛载，五穷追逐不得辞。","罗帏围香击鼍鼓，食填巨壑酒如雨。","君看白面纨袴郎，不知经史何等语。","笑我蠹鱼尘简中，口角儒墨纷异同。","腹雷昼隠吟仰屋，诧向子墨收新功。","雪毛眵眼不自恤，讥诃抵触取憎疾。","几人插羽上金銮，漫云九事八为律。","不如醇朴还吾天，抉肠剔肾谁汝怜。","且从酒徒趁落托，向来失计今差乐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-c1340a07-4ca0-4808-9306-340c479b1de2","tags":[]},{"id":"poem-0e8d9d7ea7cce398fc90d064","title":"惠山斋中听雨","author":"李详","dynasty":"宋","verses":["云冷银蟾遯，香寒宝篆迟。","轻雷新破梦，好雨故知时。","池荇阴抽带，山茶暗展旗。","空阶闻夜响，楚客起题诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-165d4e40-27a8-4582-b02a-6b875fc2f0a5","tags":[]},{"id":"poem-0e94a6eb9219a6e1e2e2eb7a","title":"歙郡有黄山楼北瞰黄山山势中拆若巨门状因题一绝","author":"于德晦","dynasty":"唐","verses":["黟峰翠色自天流，直下青冥豁素秋。","闲倚朱栏频北望，只宜名作巨门楼。","（〖1〗诗见康熙十八年闵麟嗣撰《黄山志定本》卷六，乾隆间刊刻。","此诗承仪征吴白匋先生见告。","按原志附注曰：「程弘志云：按《一统志》：刺史有从兄弃官学道，号于方外，刺史为筑室于问政山，山始名问政。","」望按：《金石萃编》卷八十有于德晦题名，在李虞仲题名之左，曰「监察御史于德晦」，题名后纪「大中六年三月廿四日」云云。","又《长安志》务本坊有左散骑常侍于德晦宅。","〖大兴徐松撰《唐两京城坊考》卷二所记同〗）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-aed8507c-b048-4459-8bbf-e0e1c8923d71","tags":["黄山"]},{"id":"poem-0eb674dc12b6db2c7f670311","title":"桂","author":"王镃","dynasty":"宋","verses":["金虫镂月影玲珑，璧叶将秋锁翠栊。","昨夜楼台风露冷，几人魂梦入林中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-5aaae42b-f243-47ea-82ed-9e97c2c2aff7","tags":[]},{"id":"poem-0eb8440e1a520334b2cdeaf4","title":"花石长枕歌荅章居士赠","author":"皎然","dynasty":"唐","verses":["楚山有石郢人琢，琢成长枕知是玉。","全疑冰片坐恐销，间发花藂惊不足。","赠予比之金琅玕，琼花烂熳浮席端。","吾师道吾不执宝，今日感君因执看。","试叩铿然应清律，纤尘不留蝇敢拂。","万物皆因造化资，如何独负清贞质。","南山有云鹄在空，长松为我生凉风。","高友朗咏乐其中，行住四仪皆道意。","不学小乘一曲士，唯将此物安座隅，取次闲眠有禅味。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-a209fb14-de5a-42d6-8555-33f71a0cab7f","tags":[]},{"id":"poem-0eba3b0a2d90d932b6f77e91","title":"咏史诗 华亭","author":"胡曾","dynasty":"唐","verses":["陆机西没洛阳城，吴国春风草又青。","惆怅月中千岁鹤，夜来犹为唳华亭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-77628860-7554-441c-b049-9120a53042a7","tags":[]},{"id":"poem-0ec575ea0536b1706b927449","title":"雨中远望","author":"宋伯仁","dynasty":"宋","verses":["山匝浓云水匝天，秋容黯淡荻花边。","潇湘八景谁收去，留下波心小钓船。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-4712cb7a-fecd-4b4a-a1a7-cb8e6376c1f8","tags":[]},{"id":"poem-0ec8c7766b8df101da912d59","title":"浣溪沙·庚申除夜","author":"纳兰性德","dynasty":"清","verses":["收取闲心冷处浓，舞裙犹忆柘枝红。","谁家刻烛待春风。","竹叶樽空翻采燕，九枝灯灺颤金虫。","风流端合倚天公。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-13","tags":[]},{"id":"poem-0ed08263075b6d37c46d6af4","title":"采桑子·白衣裳凭朱阑立","author":"纳兰性德","dynasty":"清","verses":["白衣裳凭朱阑立，凉月趖西。","点鬓霜微，岁晏知君归不归。","残更目断传书雁，尺素还稀。","一味相思，准拟相看似旧时。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-90","tags":[]},{"id":"poem-0ed15c92706d4e4dcb5e1306","title":"蝶恋花·辛苦最怜天上月","author":"纳兰性德","dynasty":"清","verses":["辛苦最怜天上月，一夕如环，夕夕都成玦。","若似月轮终皎洁，不辞冰雪为卿热。","无那尘缘容易绝，燕子依然，软踏帘钩说。","唱罢秋坟愁未歇，春丛认取双栖蝶。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-138","tags":[]},{"id":"poem-0ef5e50494d8af82563262eb","title":"上冯使君五首 五","author":"贯休","dynasty":"唐","verses":["仁政无不及，乳獭将子行。","谁家苦竹林，中有读书声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2ba0bdf9-9c3b-4f2e-be4c-cb31824c1385","tags":[]},{"id":"poem-0efa5fe898973b40cf4f7663","title":"哭程晦夫  其二","author":"孙嵩","dynasty":"宋","verses":["尚谓乡邦离有合，忍闻丘垄夜无晨。","夕阳古道曾经别，肠断西风泪满巾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b93d6e3a-edcd-4bd0-b401-7f1a41f4096a","tags":[]},{"id":"poem-0efdde2438c0eaf1ba2125f7","title":"驻马听","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["书寄乡关，说起教人心痛酸。","你传示俺八旬爹妈，道与我两月妻房，隔涉万水千山。","啼痕缄外翠绡斑，梦魂飞绕银屏远，(合)报道平安，想一家贺喜，只说道他日再相见。","(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5133","tags":[]},{"id":"poem-0f014b5796a3e29e67095512","title":"题弋阳徐明府水亭","author":"张祜","dynasty":"唐","verses":["小邑不劳贤，心期胜地偏。","树微青嶂耸，沙浅碧波旋。","荡桨投昏岸，烧燔指湿烟。","板簷傍眺寺，石路上登舡。","水槛推衣浴，风轩侧枕眠。","无因长寄此，吟和酒中仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-852966ee-e24a-40e8-be08-f9b7987aec6d","tags":[]},{"id":"poem-0f086d6e991ab03d3531c921","title":"寄雍陶先辈","author":"刘得仁","dynasty":"唐","verses":["久别青云士，幽人分固然。","愁心不易去，蹇步卒难前。","尽落经霜叶，频阴欲雪天。","归山自有限，岂待白头年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-74011ffb-7b38-471b-a8ad-b3b0e7c23bd3","tags":[]},{"id":"poem-0f17e9b3ac071a98577776b4","title":"昔昔盐二十首 那能惜马蹄","author":"赵嘏","dynasty":"唐","verses":["云中路杳杳，江畔草凄凄。","妾久垂珠泪，君何惜马蹄。","边风悲晓角，营月怨春鼙。","未道休征战，愁眉又复低。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e2bbe4d4-f485-4424-be34-83249854b040","tags":[]},{"id":"poem-0f1823fcd2afc1f9fab930ee","title":"同群公出猎海上","author":"高适","dynasty":"唐","verses":["畋猎自古昔，况伊心赏俱。","偶与群公游，旷然出平芜。","层阴涨溟海，杀气穷幽都。","鹰隼何翩翩，驰骤相传呼。","豺狼窜榛莽，麋鹿罹艰虞。","高鸟下骍弓，困兽鬬匹夫。","尘惊大泽晦，火燎深林枯。","失之有余恨，获者无全躯。","咄彼工拙间，恨非指踪徒。","犹怀老氏训，感叹此欢娱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e6078251-050b-4d8b-b77c-f416392eecf8","tags":[]},{"id":"poem-0f18bd2efe435521f9a61418","title":"减字木兰花·一尊薄酒","author":"陈瓘","dynasty":"宋","verses":["一尊薄酒。","满酌劝君君举手。","不是亲朋。","谁肯相从寂寞滨。","人生如梦。","梦里惺惺何处用。","盏到休辞。","醉后全胜未醉时。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-562","tags":[]},{"id":"poem-0f1d2592722c85f3d7190da8","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["本为泉下人，谢你救我一命存。","只恨我不久身广，报不得媳妇恩。","(合前)(夫唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5051","tags":[]},{"id":"poem-0f22fa38d1c959776199a1e2","title":"易水送别","author":"骆宾王","dynasty":"唐","verses":["此地别燕丹，壮士发冲冠。","昔时人已没，今日水犹寒。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-易水送別","tags":[]},{"id":"poem-0f254c22da75d33c9d593da8","title":"浣溪沙·红蓼渡头秋正雨","author":"薛昭蕴","dynasty":"五代","verses":["红蓼渡头秋正雨，印沙鸥迹自成行，整鬟飘袖野风香。","不语含颦深浦里，几回愁煞棹船郎，燕归帆尽水茫茫。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-26","tags":[]},{"id":"poem-0f26fe3551177acf5c961359","title":"虢国夫人","author":"杜甫","dynasty":"唐","verses":["虢国夫人承主恩，平明上马入宫门。","却嫌脂粉涴颜色，澹埽蛾眉朝至尊。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-15180235-db35-499b-8fd5-b8d9fa92f5f2","tags":["写人","七言绝句","唐诗三百首","讽刺"]},{"id":"poem-0f2cf3c03d298730a3a174e8","title":"山居诗  其二○","author":"释延寿","dynasty":"宋","verses":["自甘疏拙懒经营，大道从来戒满盈。","但起贪心迷有限，谁能触目悟无生。","云融远景危峰小，风戛寒溪野艇横。","禅后不妨敷六义，祇图歌出野人情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f7cc3ee3-c738-4b7c-bf1a-4f083441742e","tags":[]},{"id":"poem-0f35d2d01521a41e579e9c80","title":"衡门","author":"佚名","dynasty":"先秦","verses":["衡门之下，可以栖迟。泌之洋洋，可以乐饥。","岂其食鱼，必河之鲂？岂其取妻，必齐之姜？","岂其食鱼，必河之鲤？岂其取妻，必宋之子？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-137","tags":[]},{"id":"poem-0f362ea30ca0d0b69c419859","title":"次韵翁士秀雪再作","author":"曾协","dynasty":"宋","verses":["尚记东郊千顷白，夜不闻声晓盈尺。","飘洒速若赴敌兵，密阵横空谁督责。","且从膏泽落田畴，不厌寒威凌枕席。","朅来重见冻云凝，似欲飞花袭遗迹。","起寻藜杖行东皋，麦陇芊芊净摇碧。","平生殷雷转空肠，此日准拟千仓积。","老农甚喜天破悭，尊酒相携慰疲剧。","土膏渗漉入锄犂，丁宁孙子耕须力。","劝农使君软语多，莫待官侬费鞭策。","人言回天古所难，坐变乐岁须臾间。","丈夫行志自其所，会作一朝黄鹄举。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-9dfe73bd-1a3a-479f-93c0-41f69baa0cd1","tags":[]},{"id":"poem-0f3e997b78a56e32e06b0062","title":"西楼望月","author":"张籍","dynasty":"唐","verses":["城西楼上月，复是雪晴时。","寒夜共来望，思乡独下迟。","幽光落水堑，净色在霜枝。","明日千里去，此中还别离。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6001b891-e317-4a8e-aa59-891d271b95a9","tags":[]},{"id":"poem-0f3efaddeb16f51639b5889a","title":"采莲实催・采莲令·露华霞液","author":"史浩","dynasty":"宋","verses":["露华霞液，云桨椒醑，姿玉斝金罍。","交酬成雅会。","拚沈醉。","中山千日，未为长久，今此陶陶一饮，动经万祀。","陈果蓏，皆是奇异。","似瓜如斗尽备。","三千岁。","一熟珍味。","饤坐中，莹似玉、爽口流涎，三偷不枉，西真指议。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-0","tags":[]},{"id":"poem-0f4237aa95506d70d3402fd0","title":"下楼","author":"李益","dynasty":"唐","verses":["话旧全应老，逢春喜又悲。","看花行拭泪，倍觉下楼迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-44852ba9-ebb5-4651-8b5a-62e293438389","tags":[]},{"id":"poem-0f44eb4874d8a42b9c57638c","title":"江城子·晚日金陵岸草平","author":"欧阳炯","dynasty":"五代","verses":["晚日金陵岸草平，落霞明，水无情，六代繁华，暗逐逝波声。","空有姑苏台上月，如西子镜照江城。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-11","tags":[]},{"id":"poem-0f45743d87478e95e11d8850","title":"九思·怨上","author":"王逸","dynasty":"汉","verses":["令尹兮謷謷，群司兮譨譨。","哀哉兮淈淈，上下兮同流。","菽藟兮蔓衍，芳虈兮挫枯。","朱紫兮杂乱，曾莫兮别诸。","倚此兮岩穴，永思兮窈悠。","嗟怀兮眩惑，用志兮不昭。","将丧兮玉斗，遗失兮钮枢。","我心兮煎熬，惟是兮用忧。","进恶兮九旬，复顾兮彭务。","拟斯兮二踪，未知兮所投。","谣吟兮中野，上察兮璇玑。","大火兮西睨，摄提兮运低。","雷霆兮硠磕，雹霰兮霏霏。","奔电兮光晃，凉风兮怆凄。","鸟兽兮惊骇，相从兮宿栖。","鸳鸯兮噰噰，狐狸兮徾徾。","哀吾兮介特，独处兮罔依。","蝼蛄兮鸣东，蟊蠽兮号西。","蛓缘兮我裳，蠋入兮我怀。","虫豸兮夹余，惆怅兮自悲。","伫立兮忉怛，心结縎兮折摧。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-57","tags":[]},{"id":"poem-0f45a14831077d54fb93c345","title":"荷叶杯·歌发谁家筵上","author":"顾敻","dynasty":"五代","verses":["歌发谁家筵上，寥亮。","别恨正悠悠，兰釭背帐月当楼。","愁么愁，愁么愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-22","tags":[]},{"id":"poem-0f4761008484f66921841b96","title":"三代门 再吟","author":"周昙","dynasty":"唐","verses":["东邻不事事西邻，御物卑和物自亲。","天下言知天下者，兆人无主属贤人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9d76fbbb-4ab7-4fe5-a40b-a0c7850bd7df","tags":[]},{"id":"poem-0f589703a37c248e9649c9ed","title":"咏史诗 绵山","author":"胡曾","dynasty":"唐","verses":["亲在要君召不来，乱山重叠使空回。","如何坚执尤人意，甘向岩前作死灰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2915ab6c-a9d3-42a9-85c8-066bffae9c3a","tags":[]},{"id":"poem-0f62e4afe7a016dc79ce6378","title":"送恒操上人归江外觐省","author":"卢纶","dynasty":"唐","verses":["依佛不违亲，高堂与寺邻。","问安双树晓，求膳一僧贫。","持呪过龙庙，翻经化海人。","还同惠休去，儒者亦沾巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e1255db2-ff1c-49ff-b4b0-9914fbad280e","tags":[]},{"id":"poem-0f6645ec728b83e216a2110e","title":"浣溪沙·风压轻云贴水飞","author":"李煜","dynasty":"五代","verses":["风压轻云贴水飞，乍晴池馆燕争泥。","沈郎多病不胜衣。","沙上未闻鸿雁信，竹间时听鹧鸪啼。","此情唯有落花知。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-37","tags":[]},{"id":"poem-0f705017a124af3f6d1ef8e7","title":"荣华乐","author":"李贺","dynasty":"唐","verses":["鸢肩公子二十余，齿编贝，唇激朱。","气如虹霓，饮如建瓴。","走马夜归呌严更，径穿复道游椒房。","龙裘金玦杂花光，玉堂调笑金楼子。","台下戏学邯郸倡，口吟舌话称女郎。","锦祛绣面汉帝旁，得明珠十斛。","白璧一双，新诏垂金曳紫光煌煌。","马如飞，人如水。","九卿六官皆望履，将回日月先反掌。","欲作江河唯画地，峨峨虎冠上切云。","竦劒晨趋凌紫氛，绣段千寻贻皂隶。","黄金百镒贶家臣，十二门前张大宅。","晴春烟起连天碧，金铺缀日杂红光。","铜龙啮环似争力，瑶姬凝醉卧芳席。","海素笼窗空下隔，丹穴取凤充行庖。","貜貜如拳那足食，金蟾呀呀兰烛香。","军装武妓声琅珰，谁知花雨夜来过。","但见池台春草长，嘈嘈弦吹匝天开。","洪厓箫声遶天来，天长一矢贯双虎。","云弝绝骋聒旱雷，乱袖交竿管儿舞。","吴音绿鸟学言语，能教刻石平紫金。","解送刻毛寄新兔，三皇皇后七贵人。","五十校尉二将军，当时飞去逐彩云，化作今日京华春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5ec67bba-ece4-49ff-81b0-455d662a0be2","tags":[]},{"id":"poem-0f744fa0d2846fb00e524dbf","title":"哭胡十八遇","author":"张籍","dynasty":"唐","verses":["早得声名年尚少，寻常志气出风尘。","文场继续成三代，家族辉华在一身。","幼子见生才满月，选书知写未呈人。","送君帐下衣裳白，数尺坟头栢树新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1d7fc68f-be35-464b-b70a-06725f99238a","tags":[]},{"id":"poem-0f7d1538128e7f04f8cf6662","title":"赠臧文仲四首  其二","author":"陈造","dynasty":"宋","verses":["夫君根柢学，宜我屡即之。","罢马取长道，顾肯过我为。","索宝黔娄家，怪君焉取斯。","颇尝见此客，且用诧吾儿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-d0dc1db8-4099-4f52-b7ba-b98d024b5bec","tags":[]},{"id":"poem-0f865ae3460f41e134e9801b","title":"九思·悼乱","author":"王逸","dynasty":"汉","verses":["嗟嗟兮悲夫，殽乱兮纷挐。","茅丝兮同综，冠屦兮共絇。","督万兮侍宴，周邵兮负刍。","白龙兮见射，灵龟兮执拘。","仲尼兮困厄，邹衍兮幽囚。","伊余兮念兹，奔遁兮隐居。","将升兮高山，上有兮猴猿。","欲入兮深谷，下有兮虺蛇。","左见兮鸣鵙，右睹兮呼枭。","惶悸兮失气，踊跃兮距跳。","便旋兮中原，仰天兮增叹。","菅蒯兮楙莽，雚苇兮仟眠。","鹿蹊兮躖躖，貒貉兮蟫蟫。","鹯鹞兮轩轩，鹑鹌兮甄甄。","哀我兮寡独，靡有兮齐伦。","意欲兮沉吟，迫日兮黄昏。","玄鹤兮高飞，曾逝兮青冥。","鸧鹒兮喈喈，山鹊兮嘤嘤。","鸿鸬兮振翅，归雁兮于征。","吾志兮觉悟，怀我兮圣京。","垂屣兮将起，跓俟兮硕明。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-61","tags":[]},{"id":"poem-0f8e87f19705f67fd82f4b4b","title":"灵峰雪崖长老请赞","author":"释了惠","dynasty":"宋","verses":["老骨檛，恶冤家。","无面目不听别人处分，得人憎不堪师位安排。","衲僧要识渠端的，雪瀑千寻泻断崖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-4e748ad1-b57c-43ea-8553-cfeed81d15b9","tags":[]},{"id":"poem-0f8ffa1a9a6ab188a82eab4e","title":"临江仙·梦后楼台高锁","author":"晏几道","dynasty":"宋","verses":["梦后楼台高锁，酒醒帘幕低垂。","去年春恨却来时。","落花人独立，微雨燕双飞。","记得小苹初见，两重心字罗衣。","琵琶弦上说相思。","当时明月在，曾照彩云归。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-19","tags":["宋词三百首"]},{"id":"poem-0f8ffd92fa10bedbfeb09be6","title":"归田乐引・归田乐·对景还销瘦","author":"黄庭坚","dynasty":"宋","verses":["对景还销瘦。","被个人、把人调戏，我也心儿有。","忆我又唤我，见我嗔我，天生教人怎生受。","看承幸厮勾。","又是尊前眉峰皱。","是人惊怪，冤我忒撋就。","拼了又舍了，定是这回休了，及至相逢又依旧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-777","tags":[]},{"id":"poem-0f98b840b966d0b90f399571","title":"同吕缙叔诸君寄怀希用师","author":"苏颂","dynasty":"宋","verses":["方袍为佛者，学术以儒兼。","迹慕山林逸，心从典籍潜。","白云中寄趣，浮世外安恬。","遐想观书室，焚香正下帘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d4189d4d-4f21-4114-a7da-ef0b81c175c2","tags":[]},{"id":"poem-0fad70e04571d124d74c0481","title":"渊圣皇帝赐宝剑生铁花感而赋诗","author":"李纲","dynasty":"宋","verses":["靖康虏骑窥帝𬮱，中原惨澹生烟尘。","帝谓细柳真将军，总兵欲使挥浮云。","解赐宝剑御府珍，鱼肠盘屈松桧纹。","缕金错翠舟瑶琨，剸截犀象如羔豚。","驱逐狂寇出边垠，妖腰乱领徒纷纷。","龙吟蛟吼清夜闻，乃知此物能通神。","迩来杜门空念恩，旧事谁复可共论。","今晨开匣观龙文，铁花绣涩苍藓痕。","东南卑湿相蒸熏，坐使三尺光铓昏。","安得砺砥来峨岷，淬锋歛锷硎发新。","霜寒冰滑无皵皲，指麾尚可清妖氛。","愿提此剑平戎獯，犬羊虽众气可吞。","手斩可汗羁可敦，天旋日转还两君。","书铭却勒燕然勋，摅愤刷耻志乃伸。","壮怀聊可垂乾坤，缇绣什袭传仍昆。","卫绾之赐何足云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-ce82e223-4eab-43f4-b02d-eceba73a342f","tags":[]},{"id":"poem-0fb192cbaeb7adbfd71e883b","title":"和左司元郎中秋居十首 二","author":"张籍","dynasty":"唐","verses":["有地唯栽竹，无池亦养鹅。","学书求墨迹，酿酒爱朝和。","古镜铭文浅，神方谜语多。","居贫闲自乐，豪客莫相过。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-551395d4-51fe-4705-b567-6374534816d2","tags":[]},{"id":"poem-0fba4c90ce7fc0963ab43817","title":"迷神引·一叶扁舟轻帆卷","author":"柳永","dynasty":"宋","verses":["一叶扁舟轻帆卷。","暂泊楚江南岸。","孤城暮角，引胡茄怨。","水茫茫，平沙雁、旋惊散。","烟敛寒林簇，画屏展。","天际遥山小，黛眉浅。","旧赏轻抛，到此成游宦。","觉客程劳，年光晚。","异乡风物，忍萧索、当愁眼。","帝城赊，秦楼阻，旅魂乱。","芳草连空阔，残照满。","佳人无消息，断云远。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-153","tags":["宋词三百首"]},{"id":"poem-0fbd538f0ab0f66586c65c0a","title":"下第后春日长安寓居三首 一","author":"薛能","dynasty":"唐","verses":["一榜尽精选，此身犹陆沈。","自无功谠分，敢抱怨尤心。","暖陌开花气，春居闭日阴。","相知岂不有，知浅未知深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-228fa652-eea8-4900-b4cc-21327395011b","tags":[]},{"id":"poem-0fdc09e6b5f89e2b61dd64c9","title":"春夜闻笛","author":"李益","dynasty":"唐","verses":["寒山吹笛唤春归，迁客相看泪满衣。","洞庭一夜无穷雁，不待天明尽北飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-590153bb-2f4d-419d-84ac-c4b9cb785a48","tags":["洞庭湖"]},{"id":"poem-0fdc95d57e5299b964b94e3c","title":"蓟北春怀","author":"张籍","dynasty":"唐","verses":["渺渺水云外，别来音信稀。","因逢过江使，却寄在家衣。","问路更愁远，逢人空说归。","今朝蓟城北，又见塞鸿飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-737fcd5c-9ed6-4009-acc6-c279c05d3b55","tags":[]},{"id":"poem-0fe498ccba4486a92ea79cb4","title":"杨柳枝·南内墙东御路傍","author":"温庭筠","dynasty":"唐","verses":["南内墙东御路傍，须知春色柳丝黄。","杏花未肯无情思，何事行人最断肠。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-30","tags":[]},{"id":"poem-0fe66317022eecfd6fa644ae","title":"晓别","author":"张祜","dynasty":"唐","verses":["翠羽朱冠碧树鸡，未鸣先下短墙啼。","窗间谢女青蛾敛，门外萧郎白马嘶。","斜汉繁星当烛尽，淡烟残月映花迷。","景阳宫里晨钟动，不语垂鞭上柳堤。","（《全唐诗》卷五七八作温庭筠诗，题作《赠知音》。","别《才调集》卷二、《文苑英华》卷二八八亦作温诗。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-86b72a41-0eff-4077-a4f6-8d308c5e339d","tags":[]},{"id":"poem-0ffffa7b9aba29ab4d099f2d","title":"蝶恋花·杨柳秋千旗斗舞","author":"张镃","dynasty":"宋","verses":["杨柳秋千旗斗舞。","漠漠轻烟，罩定黄鹂语。","红滴海棠娇半吐。","燕脂水似朝来雨。","行过池边携手路。","都把多情，变作无情绪。","惟有东风知住处。","凭君送取温存去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-356","tags":[]},{"id":"poem-1004c84ad37f295df08215cd","title":"与朱山人","author":"杜甫","dynasty":"唐","verses":["锦里先生乌角巾，园收芋栗未全贫。","惯看宾客儿童喜，得食阶除鸟雀驯。","秋水才深四五尺，野航恰受两三人。","白沙翠竹江村暮，相送柴门月色新。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-與朱山人","tags":[]},{"id":"poem-1004d659fc5838f1247ea1a5","title":"花心动·槐夏阴浓","author":"史浩","dynasty":"宋","verses":["槐夏阴浓，笋成竿、红榴正堪攀折。","菖歜碎琼，角黍堆金，又赏一年佳节。","宝觥交劝殷勤愿，把玉腕、彩丝双结。","最好是，龙舟竞夺，锦标方彻。","此意凭谁向说。","纷两岸，游人强生区别。","胜负既分，些个悲欢，过眼尽归休歇。","到头都是强阳气，初不悟、本无生灭。","见破底，何须更求指诀。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-117","tags":[]},{"id":"poem-1011b47593622c73fb4ad41e","title":"六州歌头·凭深负阻","author":"刘褒","dynasty":"宋","verses":["凭深负阻，蜂舞肆奔腾。","龙江上，妖氛涨，鲸海外，白波惊。","羽檄交飞急，玉帐静，金韬閟，恢远驭，振长樱。","密分兵。","细草黄沙渺渺，西关路、风袅高旌。","听飞霜令肃，坚壁夜无声。","鼓角何神。","地中鸣。","看追风骑，攒云槊，雷野毂，激天钲。","飞箭集，旄头坠，长围掩，郭东倾。","振旅观旋凯，笳鼓竞，绣旗明。","刀换犊，戈藏革，士休营。","黄色赤云交映，论功何止蔡州平。","想环城苍玉，深刻入青冥。","永诏来今。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-306","tags":[]},{"id":"poem-1013bc5d48c55d891439d905","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["它还是把奴辜，实是记不得苦。","到京里果不管，下死工夫。","(净)下梢头有团圆日。","(旦)既为官，怕迤逦向人疏。","(末)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2648","tags":[]},{"id":"poem-101b7637d3a6783fff534c11","title":"崇义里滞雨","author":"李贺","dynasty":"唐","verses":["落莫谁家子，来感长安秋。","壮年抱羁恨，梦泣生白头。","瘦马秣败草，雨沫飘寒沟。","南宫古帘暗，湿景传签筹。","家山远千里，云脚天东头。","忧眠枕劒匣，客帐梦封侯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-840a294d-06b8-45a1-9751-fa3e97c881ee","tags":["写雨","秋天","抒怀","雨","怀才不遇","愤懑"]},{"id":"poem-101c58b9ef92970ad4492c44","title":"宿潭上二首 一","author":"畅当","dynasty":"唐","verses":["夜潭有仙舸，与月当水中。","嘉宾爱明月，游子惊秋风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-dabec09f-0fd1-4a09-b0c2-c3aae3db4c82","tags":[]},{"id":"poem-101e29257028ef4e9bbe1593","title":"浣溪沙·青杏园林著酒香","author":"晏殊","dynasty":"宋","verses":["青杏园林著酒香。","佳人初试薄罗裳。","柳丝无力燕飞忙。","乍雨乍晴花自落，闲愁闲闷日偏长。","为谁消瘦减容光。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-434","tags":[]},{"id":"poem-101fee93891d040ba159086a","title":"生查子·繁灯夺霁华","author":"刘克庄","dynasty":"宋","verses":["繁灯夺霁华。","戏鼓侵明发。","物色旧时同，情味中年别。","浅画镜中眉，深拜楼西月。","人散市声收，渐入愁时节。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-52","tags":["宋词三百首"]},{"id":"poem-104321d5a5ad276cc80a43da","title":"郊庙歌辞 梁太庙乐舞辞 来仪舞","author":"不详","dynasty":"唐","verses":["于赫帝命，应天顺人。","亭育品汇，宾礼百神。","洪基永固，景命惟新。","肃恭孝享，祚我生民。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-32a6054f-b534-4e84-b350-3ac909640f93","tags":[]},{"id":"poem-104799c626424e3185dc2ecf","title":"短歌行赠王郎司直","author":"杜甫","dynasty":"唐","verses":["王郎酒酣拔劒斫地歌莫哀，我能拔尔抑塞磊落之奇才。","豫章翻风白日动，鲸鱼跋浪沧溟开。","且脱佩劒休裴回，西得诸侯櫂锦水。","欲向何门趿珠履，仲宣楼头春色深。","青眼高歌望吾子，眼中之人吾老矣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7d187686-9944-4690-bc0c-5716539e1a1d","tags":["悲伤","抒情","送别","怀才不遇"]},{"id":"poem-1047e755a31732d72a6aba3c","title":"清平乐·红笺小字","author":"晏殊","dynasty":"宋","verses":["红笺小字。","说尽平生意。","鸿雁在云鱼在水。","惆怅此情难寄。","斜阳独倚西楼。","遥山恰对帘钩。","人面不知何处，绿波依旧东流。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-162","tags":["宋词三百首"]},{"id":"poem-104d3fd6c589558652c910ed","title":"奉和御制旋师喜捷","author":"裴漼","dynasty":"唐","verses":["殊类骄无长，王师示有征。","中军才受律，妖寇已亡精。","斩虏还遮塞，绥降更筑城。","从来攻必克，天策振奇兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8999600e-5b3f-44a0-9c15-a8b309a2f3c0","tags":[]},{"id":"poem-10544db412f81a199f7a44e8","title":"荆山","author":"释居简","dynasty":"宋","verses":["隠不知山浅，端如璞在荆。","草滋皆玉色，松籁作江声。","莽莽嫌吟俗，滔滔笑渭清。","莫将云锦橐，容易小能名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-5cf541d5-b0a7-4401-8e5d-b8d625c40b6b","tags":[]},{"id":"poem-1060562c69fe5a5e09ec73f1","title":"偈颂（幷序○序为南岳齐己撰） 二十二","author":"居遁","dynasty":"唐","verses":["拟学论情实苦哉，疑心不断妄难摧。","未了携囊须且去，得闲无事却肯伊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-004a2f19-0437-4d4f-ad42-0fd032d98f6c","tags":["衡山"]},{"id":"poem-1060ccc69055bb9f66e47f2f","title":"从吕扬州觅芍药栽","author":"张栻","dynasty":"宋","verses":["扬州风物故依然，梦想他时楚水边。","乞与灵根归自种，梢头茧栗看新年。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-e36e3f42-ad16-49a5-9c76-f8396782de64","tags":[]},{"id":"poem-1068ab8d0516c8d4842462e0","title":"梅花二首  其二","author":"林宪","dynasty":"宋","verses":["池边石陂陀，水光上梅梢。","石上古隶字，藓剥风萧骚。","树老花秀发，冰生香动摇。","只恐字磨灭，不愁花寂寥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-cfe6887c-a36c-46e4-a55a-3a3719623bfc","tags":[]},{"id":"poem-106c889ff7525ca29e6848c3","title":"鼓吹曲辞 巫山高","author":"李端","dynasty":"唐","verses":["巫山十二峰，皆在碧虚中。","回合云藏日，霏微雨带风。","猨声寒过水，树色暮连空。","愁向高唐望，清秋见楚宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a5a4b9de-6628-40ce-8e63-6e433f69997d","tags":[]},{"id":"poem-1070b459082e5e59f673f74f","title":"新晴爱月","author":"陆畅","dynasty":"唐","verses":["野性平生惟爱月，新晴半夜覩婵娟。","起来自擘纱窗破，恰漏清光落枕前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-13816ee9-b5c3-456c-947c-6b8cab1c4f4e","tags":[]},{"id":"poem-10755cc8665fb30999d72228","title":"君子于役","author":"佚名","dynasty":"先秦","verses":["君子于役，不知其期。曷至哉？鸡栖于埘。日之夕矣，羊牛下来。君子于役，如之何勿思！","君子于役，不日不月。曷其有佸？鸡栖于桀。日之夕矣，羊牛下括。君子于役，苟无饥渴？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-65","tags":[]},{"id":"poem-10829ee576aa6cb51f876094","title":"惠文太子挽歌","author":"袁瓘","dynasty":"唐","verses":["寒仗丹旄引，阴堂白日违。","暗灯明象物，画水湿灵衣。","羽化淮王去，仙迎太子归。","空余燕衔土，朝夕向陵飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0dc587aa-2bc9-4f31-aa81-9165ed6e39c4","tags":[]},{"id":"poem-1086ff575fbee50ba02f9b47","title":"馆西迎驾起居","author":"苏颂","dynasty":"宋","verses":["一梢鸣跸启重关，广殿传呼趣就班。","瑞日初临黄盖外，紫云先绕翠裘间。","和鸾音里趋翔过，锦绣围中拜舞还。","共诧书林清近地，彤墀咫尺对天颜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-6040b455-eb12-46f8-a126-37b99c92cd76","tags":[]},{"id":"poem-1093e1837ddd0285dd328e33","title":"刘泼帽","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我每不久须倾弃，叹当初足我不是。","苦！不如我死了到无他虑。","(合)一度思量，一度也肝肠碎。","(净唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4995","tags":[]},{"id":"poem-10986d4d25eb9d7bf779189e","title":"送防秋将","author":"张籍","dynasty":"唐","verses":["白首征西将，犹能射戟支。","元戎选部曲，军吏换旌旗。","逐虏招降远，开边旧垒移。","重收陇外地，应似汉家时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b0173008-7777-4799-afe3-7e1b4bd1ce89","tags":[]},{"id":"poem-10a251deb6a53b81365af105","title":"减字木兰花·距春五日","author":"程大昌","dynasty":"宋","verses":["距春五日。","吉语搀先来饮席。","易卦占新。","八八周轮又再轮。","开年定好。","定把笙歌更药裹。","旧怕无孙。","今已蓝袍拥绣荪。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-232","tags":[]},{"id":"poem-10a45f787d1db92ae7cd90ab","title":"吴公约神道碑附诗","author":"罗隐","dynasty":"唐","verses":["吴山苍苍，吴水泱泱。","降生英灵，为公为王。","以严师旅，以奠封疆。","派有别者，我亦鹰扬。","取直之功，捍巢之绩。","虽从本军，实展良画。","践历禁旅，光扬事迹。","乃自西佳，迁于硖石。","上君东代，诸将西征，贾其余通，资其锐兵。","稽山雾廓，京口波清。","再从貂冕，始拜冬卿。","吴会纷纭，淮[右]（石）（从雍文华校本改）奔竞。","驱其涷馁，犯我疆境。","躬励精卒，恭承上命。","雪霁松贞，风中草劲。","元戎承制，圣主酬劳。","大起名重，司元望高。","优游渥泽，出入官曹。","所谓鸡省，全资豹韬。","恭仰府城，载崇吾圉。","惟力是助，厥功以举。","云矗千堵，土攒万杵。","率以资产，役以军旅。","乃颁异宠，乃正华资。","大国纲纪，雄藩羽仪。","床间牛鬬，杯里蛇疑。","天胡可测，神亦难知。","有仁于时，有功于物。","一代殊勋，二品清秩。","不谓不达，何获何失。","瑞马神羊，金箱玉室。","（出《全唐文》卷八九七。","）（〖1〗碑云：「君嗣子以隐乡里之旧，请铭其墓。","而复以诗一章，文其美于道之隅。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a5065b2f-16eb-47ad-aa50-886d06a42ec2","tags":[]},{"id":"poem-10b7f9d94a6e52f673b80f03","title":"重阳","author":"高适","dynasty":"唐","verses":["节物惊心两鬓华，东篱空绕未开花。","百年将半仕三已，五亩就荒天一涯。","岂有白衣来剥啄，一从乌帽自攲斜。","真成独坐空搔首，门柳萧萧噪暮鸦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c1fa02b3-3fdd-4de6-86d8-264f36cfee99","tags":[]},{"id":"poem-10c2cd9b24e2317544509c77","title":"上元","author":"郭利贞","dynasty":"唐","verses":["九陌连灯影，千门度月华。","倾城出宝骑，匝路转香车。","烂熳惟愁晓，周游不问家。","更逢清管发，处处落梅花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8802fc47-29ba-4564-a112-a602b5b0ebf0","tags":[]},{"id":"poem-10d3141f1a34727a8c5373c7","title":"四七","author":"王梵志","dynasty":"唐","verses":["见贵当须避，知强远利他。","（「利」，伯三五五八、伯三六五六卷作「离」。","）高飞能去纲（按当作「网」。","）岂得值低罗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-05adbd3d-d50e-4cbf-881e-bf958afc87ea","tags":[]},{"id":"poem-10e0f8e28ee8c159f765fc9a","title":"同朱山长游江郎","author":"柴元彪","dynasty":"宋","verses":["屭赑开天风，三峰互参峙。","一如植躬圭，两峰拱而侍。","削玉石为笔，书空云作纸。","岚光动九天，翠色照千里。","上有碧玉莲，中有黄金鲤。","壁界一字天，松老千年乳。","鹰旋磨云根，虎跑流石髓。","禅师久入定，色相如不死。","灵石剖鸿荒，开山自晋始。","威显三直神，肸蚃百世祀。","劫风俄扇扬，梵宇忽颓圮。","僧来自怀玉，被荆营故址。","笙鹤宴群仙，钟鱼饭德士。","佳客贲而思，空谷跫然喜。","一筇事幽讨，万象归俯视。","山茗澹以清，村醪薄而旨。","对弈覆危枰，投壶响飞矢。","盘桓苍翠间，酬酢笑谈里。","欹枕自逍遥，凭阑时徙倚。","泉琴浣我心，松筝清我耳。","庐山乐天翁，敬亭谪仙子。","今昔虽殊时，其乐亦如此。","留为他日观，岁月端可纪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-27840c7a-bf0a-4a8f-a23a-aeecdda686f8","tags":["庐山"]},{"id":"poem-10e4b9c5c1698da1acfbb7fe","title":"上元怀古二首 二","author":"李山甫","dynasty":"唐","verses":["争帝图王德尽衰，骤兴驰霸亦何为。","君臣都是一塲笑，家国共成千载悲。","排岸远樯森似槊，落波残照赫如旗。","今朝城上难回首，不见楼船索战时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-58070aff-c81d-4222-9ad2-8f8b6de6f0c9","tags":[]},{"id":"poem-10e67a5b68612393324257a6","title":"菩萨蛮 其十四","author":"温庭筠","dynasty":"唐","verses":["竹风轻动庭除冷，珠帘月上玲珑影。","山枕隐秾妆，绿檀金凤凰。","两蛾愁黛浅，故国吴宫远。","春恨正关情，画楼残点声。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-13","tags":[]},{"id":"poem-10ed0840456f08cbf176c75e","title":"浣花亭陪川主王播相公暨寮同赋早菊","author":"薛涛","dynasty":"唐","verses":["西陆行终令，东篱始再阳。","绿英初濯露，金蘂半含霜。","自有兼材用，那同众草芳。","献酬樽俎外，宁有惧豺狼。","（以上二诗见《分门纂类唐歌诗》残本第六册《草木虫鱼类》卷五。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9baf7e52-3d34-4ff3-b28d-04e0a1b00d09","tags":[]},{"id":"poem-10f07717c9ad2fb16935f02e","title":"酬诸公见过","author":"王维","dynasty":"唐","verses":["嗟予未丧，哀此孤生。","屏居蓝田，薄地躬耕。","岁[晏]输税，以奉粢盛。","晨往东臯，草露未晞。","暮看烟火，负担来归。","我闻有客，足埽荆扉。","箪食伊何，疈瓜抓枣。","仰厕群贤，皤然一老。","媿无莞簟，班荆席藁。","泛泛登陂，折彼荷花。","静观素鲔，俯映白沙。","山鸟群飞，日隐轻霞。","登车上马，倏忽云散。","雀噪荒村，鸡鸣空馆。","还复幽独，重欷累叹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-72fb2b39-9959-4985-8037-f4344492b1af","tags":[]},{"id":"poem-10f110c103f5f0c01ce5bf2e","title":"宫词  其八一","author":"张公庠","dynasty":"宋","verses":["冉冉残晖画阁西，宫人行乐恋芳时。","遥闻索辇开黄繖，不尽花前半局棋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-1014b439-4fbb-4c4a-9939-8d478cd24fa5","tags":[]},{"id":"poem-10f76d09059ffc0367c2e159","title":"敦煌廿咏（并序） 十四、半壁树咏","author":"敦煌人作品[一]","dynasty":"唐","verses":["半壁生奇木，盘根到水涯。","高柯宠（笼）宿雾，密叶隐朝霞。","二月含青翠，三秋带紫花。","森森神树下，祈赛不应赊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-beecc6e1-1682-4a49-9a03-c86501e35bd4","tags":[]},{"id":"poem-10fe1eae0c3feb44bad24ff8","title":"马诗二十三首 二十三","author":"李贺","dynasty":"唐","verses":["武帝爱神仙，烧金得紫烟。","廐中皆肉马，不解上青天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2fe1085b-c5a4-4dd5-a9e0-286066b0d923","tags":["寓人","马","借古讽今","写马"]},{"id":"poem-1102a06d9516c7e5dc41e819","title":"赠别李山人","author":"张乔","dynasty":"唐","verses":["分合老西秦，年年梦白苹。","曾为洞庭客，还送洞庭人。","语别惜残夜，思归愁见春。","遥知泊舟处，沙月自相亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-05f0b477-1b49-4a6e-a91a-ddf4d57a07f4","tags":["洞庭湖"]},{"id":"poem-1107c32b8c22a2df7e42061a","title":"如梦令·门外落花流水","author":"谢逸","dynasty":"宋","verses":["门外落花流水。","日暖杜鹃声碎。","蕃马小屏风，一枕画堂春睡。","如醉。","如醉。","正是困人天气。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-617","tags":[]},{"id":"poem-110d7b1fa47b518f6875ce2d","title":"感怀 一","author":"后主煜","dynasty":"唐","verses":["又见桐花发旧枝，一楼烟雨暮凄凄。","凭阑惆怅人谁会，不觉澘然泪眼低。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4efebbe9-a40d-4428-b82a-752c48f67793","tags":[]},{"id":"poem-111844d053403ee2b93169cb","title":"被蕃军中拘系之作","author":"马云奇","dynasty":"唐","verses":["何事逐漂蓬，悠悠过凿空！世穷途运荣（蹇），战苦不成功。","泪滴东流水，心遥北翥鸿。","可能忠孝节，长遣门阃（困）西戎。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e9c2848d-4e07-48f6-b088-df255899a11b","tags":[]},{"id":"poem-111d1ec9b4e91ad2e2719154","title":"偈颂七十一首  其二一","author":"释了惠","dynasty":"宋","verses":["年去年来，年来年去。","虽有去来年，且无来去路。","既无来去路，实无有去来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9ae1b5ef-e1f0-473c-99da-b1b188be0879","tags":[]},{"id":"poem-111ed30d0196202949e71de8","title":"应天长·平江波暖鸳鸯语","author":"毛文锡","dynasty":"五代","verses":["平江波暖鸳鸯语，两两镏般归极浦。","芦州一夜风和雨，飞起浅沙翘雪鹭。","渔灯明远渚，兰棹今宵何处。","罗袂从风轻举，愁杀采莲女。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-30","tags":[]},{"id":"poem-112120a639a0a53ea72578ac","title":"闲居","author":"熊皎","dynasty":"唐","verses":["深逢野草皆为药，静见樵人恐是仙。","（见《增修诗话总龟前集》卷十三《雅言杂载》。","）（按：《全唐诗》卷七三七收二句，缺题，今重录。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d11f5cc3-722b-48a5-bc1d-3560ae7770ec","tags":[]},{"id":"poem-1122d950ae663cb0d07b686d","title":"游老君洞  其二","author":"刘子荐","dynasty":"宋","verses":["怪怪奇奇画不如，最难得者近城郛。","他仙皆逊老君有，此洞可知天下无。","徐甲青牛骖左侍，六丁白鹤导前驱。","老仙笑我来何晚，一样须眉一样臞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-52698b0b-910f-4b0c-99c8-5958592b2637","tags":[]},{"id":"poem-113401c5368a7fe0c1c4d111","title":"杏殇 四","author":"孟郊","dynasty":"唐","verses":["儿生月不明，儿死月始光。","儿月两相夺，儿命果不长。","如何此英英，亦为吊苍苍。","甘为堕地尘，不为末世芳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2988fec5-a58f-4310-ae02-d8357b44da0f","tags":[]},{"id":"poem-113c0ad4ca46e5ebb04cab5c","title":"送友人江行之庐山肄业","author":"唐求","dynasty":"唐","verses":["蜀国初开棹，庐峰拟拾萤。","兽皮裁褥暖，莲叶制衣馨。","楚水秋来碧，巫山雨后青。","莫教衔凤诏，三度到中庭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6c5d1f75-a00a-493d-9be7-458f96e36061","tags":["庐山"]},{"id":"poem-113d09daaa23bb5147a374b3","title":"浣溪沙·记绾长条欲别难","author":"纳兰性德","dynasty":"清","verses":["记绾长条欲别难。","盈盈自此隔银湾。","便无风雪也摧残。","青雀几时裁锦字，玉虫连夜翦春旙。","不禁辛苦况相关。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-136","tags":[]},{"id":"poem-114fa7a7e6736816e3882c1d","title":"左迁至蓝关示侄孙湘","author":"韩愈","dynasty":"唐","verses":["一封朝奏九重天，夕贬潮阳路八千。","本为圣朝除弊政，敢将衰朽惜残年。","云横秦岭家何在，雪拥蓝关马不前。","知汝远来应有意，好收吾骨瘴江边。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-左遷至藍關示侄孫湘","tags":[]},{"id":"poem-11594e263683c88d1950464c","title":"兵要望江南 《周易》占候第二十六（三十七首） 三十二","author":"易静","dynasty":"唐","verses":["《易》之位，六亲与五乡。","外卦世爻子孙旺，三般有气我无伤，勿要落空亡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d8e98acd-9bb1-43fd-8a2c-665a18197ae4","tags":[]},{"id":"poem-117b23854c23604975a43a1b","title":"湖山堂","author":"曾协","dynasty":"宋","verses":["自从幽处得官居，不向良工觅画图。","青绕帘帷山极望，冷侵庭户水平铺。","渔歌历历来天外，帆影飞飞入坐隅。","俸粟有余公事少，卧听风雨落江湖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-7b8bd8a3-9cd4-430d-a8ab-d20b4434eb13","tags":[]},{"id":"poem-11816fcda1aa462cbd2bcf43","title":"和遯泽韵取临江叔父墨梅","author":"王柏","dynasty":"宋","verses":["我翁久驾白云归，谁宝冰绡一旧枝。","疎影暗香浮戯墨，光风霁月惠仙姿。","只疑和靖旧争长，纵是逃禅甘伏雌。","寄语古樵毋睥睨，青毡归我不应迟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1254c486-342c-4b29-915d-b56f2cbd7e0f","tags":[]},{"id":"poem-118f5004373f4d9e0daccc53","title":"兵要望江南 《周易》占候第二十六（三十七首） 三十四","author":"易静","dynasty":"唐","verses":["外卦动，内卦动兴爻。","内外动爻俱动发，若然我战动鎗刀，大战杀声高。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-75590a5b-8562-4f4a-a9a8-2cd591c7fdc7","tags":[]},{"id":"poem-11915021f774762c4166a303","title":"临江仙·月色穿帘风入竹","author":"顾敻","dynasty":"五代","verses":["月色穿帘风入竹，倚屏双黛愁时。","砌花含露两三枝，如啼恨脸，魂断损容仪。","香烬暗消金鸭冷，可堪辜负前期。","绣襦不整鬓鬟欹，几多惆怅，情绪在天涯。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-33","tags":[]},{"id":"poem-119346204f6a0b807c4b8819","title":"曹梦良教授寄柑一百颗报以干荔支戏成二绝  其二","author":"王十朋","dynasty":"宋","verses":["绝品知君尚未尝，三山绛帐喜相将。","冷官岂是淹贤地，尤物聊观十八娘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-e3b900fb-649e-42d8-8ed1-e5f94fad7827","tags":[]},{"id":"poem-1193a417d6be07162f660bae","title":"题水弄山","author":"杨筠","dynasty":"宋","verses":["曲曲溪流叠叠山，稻塍高下路回环。","晓暾初射林霏落，一道炊烟紫翠间。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1a117a12-18fc-4b33-ae5a-dc98099908c0","tags":[]},{"id":"poem-11951fea6f5d5750c8dcc52e","title":"送夏侯审参军游江东","author":"李嘉祐","dynasty":"唐","verses":["袖中多丽句，未遣世人闻。","醉夜眠江月，闲时逐海云。","荻花寒漫漫，鸥鸟暮群群。","若到长沙苑，渔家更待君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9c56b83a-34f3-4a30-a7fe-c0f7bb2fcac1","tags":[]},{"id":"poem-119bfc4e67e0701c16ec4a8e","title":"奉和幸白鹿观应制","author":"武平一","dynasty":"唐","verses":["玉府凌三曜，金坛驻六龙。","彩旒悬倒景，羽盖偃乔松。","玄圃灵芝秀，华池瑞液浓。","谬因沾舜渥，长愿奉尧封。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a6d93978-0137-4de2-ba3d-ed5fbbc61917","tags":[]},{"id":"poem-11a2b4df64545e7feacfa68f","title":"次韵柳郎中二咏  其一","author":"苏颂","dynasty":"宋","verses":["蒲条围坐雪添瓶，侧理糊窗炽炭明。","常对图书堆四壁，却思裘褐胜双旌。","道心生后安休息，事局闲来怕践更。","睡足定应输杜守，穷愁何必学虞卿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5b283344-201b-4be8-a4b2-d124afed6904","tags":[]},{"id":"poem-11b429cc796ac2daaa5fcf9c","title":"虞美人·少年艳质胜琼英","author":"顾敻","dynasty":"五代","verses":["少年艳质胜琼英，早晚别三清。","莲冠稳簪钿篦横，飘飘罗袖碧云轻，画难成。","迟迟少转腰身袅，翠靥眉心小。","醮坛风急杏花香。","此时恨不驾鸾凤，访刘郎。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-38","tags":[]},{"id":"poem-11b922dc188853864b9ef81a","title":"菩萨蛮·凉飙轻散馀霞绮","author":"李弥逊","dynasty":"宋","verses":["凉飙轻散馀霞绮。","疏星冷浸明河水。","敧枕画檐风。","秋生草际蛩。","雁门离塞晚。","不道衡阳远。","归恨隔重山。","楼高莫凭栏。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-15","tags":[]},{"id":"poem-11b96bc4c4d90cd41d0d6021","title":"览炼师张殷儒诗","author":"李翔","dynasty":"唐","verses":["石井峰高劈曙云，云开山露见张君。","心藏定远握中策，袖贮怀沙江上文。","巨壑波翻鲸少敌，老松巢迥鹤难群。","无端示我青霞句，吟断秋风到日曛。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4e2f895b-17df-4675-ab98-07b931cab41d","tags":[]},{"id":"poem-11bd08373734f8e65afc4c53","title":"上顾大夫","author":"贯休","dynasty":"唐","verses":["碧海漾仙洲，骊珠外无宝。","一岳倚青冥，群山尽如草。","君侯圣朝瑞，动只关玄造。","谁云倚天剑，含霜在怀抱。","谁云青云险，门前是平道。","洪民亦何幸，里巷清如扫。","至化无经纶，至神无祝祷。","即应炳文柄，孤平去浩浩。","即应调鼎味，比屋堪封保。","野人慕正化，来自海边岛。","经传髻里珠，诗学池中藻。","闭门十余载，庭杉共枯槁。","今朝投至鉴，得不倾肝脑。","斯文如未精，归山更探讨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2d6bfbad-eb99-4f8e-981e-c84f2b56f23a","tags":[]},{"id":"poem-11c648df52abf6a24307e3ac","title":"尧民歌","author":"杨景贤","dynasty":"元","verses":["露华凉罗袜湿浸浸，唬得我霞脸赤浑身上下颤兢兢。","(行者做下山科，云)小娘子，见我么？(裴女唱)走了那黑容仪换上这脸黄金，抵多少死却钟期遇知音。","难尽恁，风流两个心，不似俺鳏寡孤独甚。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4510","tags":[]},{"id":"poem-11c653d61628efb48c84fe79","title":"卜算子·我住长江头","author":"李之仪","dynasty":"宋","verses":["我住长江头，君住长江尾。","日日思君不见君，共饮长江水。","此水几时休，此恨何时已。","只愿君心似我心，定不负相思意。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-48","tags":["宋词三百首","长江"]},{"id":"poem-11d12124f1cebb447e1ad575","title":"薄媚衮","author":"施惠《幽闺记》","dynasty":"元","verses":["(生、小旦)听人报军马近城，国主迁都汴。","今晚庶民，不许一人落后在京辇。","生长升平，谁曾惯遭离乱。","苦怎言，胆颤心惊，如何可免？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2917","tags":[]},{"id":"poem-11df83d64f63ed4b7e2ec348","title":"阮郎归·小池芳草绿初匀","author":"蒋元龙","dynasty":"宋","verses":["小池芳草绿初匀。","柳寒眉尚颦。","东风吹雨细于尘。","一庭花脸皴。","莺共蝶，怨还嗔。","眼前无好春。","这般天气煞愁人。","人愁旋旋新。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-619","tags":[]},{"id":"poem-11e0846be7d3908fcb5eba72","title":"雪晴","author":"綦崇礼","dynasty":"宋","verses":["冰箸垂簷滴渐多，眼花眩目气初和。","功成尺瑞追前赋，喜兆千箱可预歌。","坐看嫩黄滋柳色，遥知新绿涨湖波。","闭门积玉浑消尽，却有儿童整雀罗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-76d2a951-cbbe-48b1-8d4f-48294ed4b829","tags":[]},{"id":"poem-11e6e3fd77a74e141d7c9c7c","title":"铁堂峡","author":"杜甫","dynasty":"唐","verses":["山风吹游子，缥缈乘险绝。","峡形藏堂隍，壁色立积铁。","径摩穹苍蟠，石与厚地裂。","修纤无垠竹，嵌空太始雪。","威迟哀壑底，徒旅惨不悦。","水寒长冰横，我马骨正折。","生涯抵弧矢，盗贼殊未灭。","飘蓬逾三年，回首肝肺热。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1b4ed54b-6c20-4817-a102-e0ce802ba019","tags":[]},{"id":"poem-11e7ef7cf95fcc0702affd50","title":"孤猿叫月","author":"王镃","dynasty":"宋","verses":["天色如冰万籁沉，攀藤无伴自惊心。","啼时只有空山应，影挂寒松夜正深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-1795ab44-3415-4502-af69-343ae501d6e5","tags":[]},{"id":"poem-11f4747e19a94c93c439c283","title":"浣溪沙·揽镜无言泪欲流","author":"孙光宪","dynasty":"五代","verses":["揽镜无言泪欲流，凝情半日懒梳头，一庭疏雨湿春愁。","杨柳只知伤离别，杏花应信损娇羞，泪沾魂断轸离忧。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-40","tags":[]},{"id":"poem-120295de4ba745ea28d45d50","title":"书边事","author":"张乔","dynasty":"唐","verses":["调角断清秋，征人倚戍楼。","春风对青冢，白日落梁州。","大汉无兵阻，穷边有客游。","蕃情似此水，长愿向南流。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8324db66-b75a-40ff-9469-cba276d2f88f","tags":["唐诗三百首","生活","五言律诗","边塞"]},{"id":"poem-120587db7be11473f190749a","title":"送大宝上人归楚山","author":"皎然","dynasty":"唐","verses":["厌上乌桥送别频，湖光烂熳望行人。","欲将夜舸陪嘉月，肯住空林伴老身。","独鹤翩翻飞不定，归云萧散会无因。","从何得道怀惆怅，莫是人间屡见春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-5e5f47ff-0f41-439a-ae00-fbae21bd80c4","tags":[]},{"id":"poem-12089396396abc772f8a30e5","title":"洛阳咏古","author":"司空图","dynasty":"唐","verses":["石勒童年有战机，洛阳长啸倚门时。","晋朝不是王夷甫，大智何由得预知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-989b140b-b6be-4437-abc8-427d0cfae843","tags":[]},{"id":"poem-1208ad025734545c5815b92c","title":"西江月","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["玉体轻流香汗，绣裙荡漾明霞。","纤纤玉手把彩绳拿，真个堪描堪画。","本是北方戎戏，移来上苑豪家。","女娘撩乱隔墙花，好似半仙戏耍。","(净丑)恁地便打秋千。","只是那里有秋千架？(末)我这花园里那讨秋千架？一来相公不忻，二来娘子又不好，纵有也拆了。","(丑)院公，没奈何，咱每三个在这里，厮论做个秋千架，一人打，两人抬。","(做架介)(末)谁先打？(净丑)我两人抬，院公，你先打。","(介)(贴旦在戏房内叫)老姥姥，将我的《列女传》那里去了？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4922","tags":[]},{"id":"poem-120c1bf11d049b30cf1dfb2a","title":"题黄鹤楼","author":"江万里","dynasty":"宋","verses":["黄鹤楼高倚半天，楼中黄鹤去千年。","檐楹自是留真境，几席何妨得老仙。","云护山光秋驻马，日笼江影昼停船。","良工改写归图画，俯仰令人一慨然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-661b417d-b5ac-4c98-983b-08613fae1c1e","tags":[]},{"id":"poem-12147db0592b1951df81ec14","title":"小游仙诗九十八首 三十一","author":"曹唐","dynasty":"唐","verses":["鹤不西飞龙不行，露干云破洞箫清。","少年僊子说闲事，遥隔彩云闻笑声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f39ea99f-85ac-4066-bd9a-381d8ebf5f4a","tags":[]},{"id":"poem-1218cc73141eb905e1d2213a","title":"荷叶杯·曲砌蝶飞烟暖","author":"顾敻","dynasty":"五代","verses":["曲砌蝶飞烟暖，春半。","花发柳垂条，花如双脸柳如腰。","娇么娇，娇么娇。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-28","tags":[]},{"id":"poem-121c6746dd642b0c27349eff","title":"颂古七十六首  其六一","author":"释士珪","dynasty":"宋","verses":["二乘菩萨何言尽，诸佛凡夫早晚休。","世事但将公道断，人心难似水长流。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-65021256-ae3d-4c92-8799-f194f72f8d5e","tags":[]},{"id":"poem-1227c2c5ac5c7fc41b1c158c","title":"十日和张少监","author":"徐铉","dynasty":"宋","verses":["重阳高会古平台，吟徧秋光始下来。","黄菊后期香未减，新诗捧得眼还开。","每因佳节知身老，却忆前欢似梦回。","且喜清时屡行乐，是非名利尽悠哉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-63b4d1a5-8963-4ad0-abd9-7d3964ca6991","tags":[]},{"id":"poem-122a9a4c4a32172d6abc66b2","title":"和贾舍人早朝","author":"岑参","dynasty":"唐","verses":["鸡鸣紫陌曙光寒，莺啭皇州春色阑。","金阙晓钟开万户，玉阶仙仗拥千官。","花迎剑佩星初落，柳拂旌旗露未干。","独有凤凰池上客，阳春一曲和皆难。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-和賈舍人早朝","tags":[]},{"id":"poem-122e94f3ff9e5552cae423c1","title":"甘园寻梅  其二","author":"释居简","dynasty":"宋","verses":["楮幌春生斗底房，不知冰结夜来霜。","无因领略黄昏月，只遣疎钟管暗香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-638a2015-c432-45c7-a047-156cf9544cb3","tags":[]},{"id":"poem-1235da409dc620f23ad12908","title":"上高侍郎","author":"高蟾","dynasty":"唐","verses":["天上碧桃和露种，日边红杏倚云栽。","芙蓉生在秋江上，不向东风怨未开。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-上高侍郎","tags":[]},{"id":"poem-123c4b1c5526671be225285b","title":"嘲聂崇义","author":"郭忠恕","dynasty":"宋","verses":["近贵全为聩，攀龙即是聋。","虽然三个耳，其奈不成聪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-762664f3-8f43-49a4-8fa5-5ec8ca1dfc83","tags":[]},{"id":"poem-12401d2ad3bfbae339874ba6","title":"华岳","author":"王维","dynasty":"唐","verses":["西岳出浮云，积雪在太清。","连天凝黛色，百里遥青冥。","白日为之寒，森沈华阴城。","昔闻乾坤闭，造化生巨灵。","右足踏方止，左手推削成。","天地忽开拆，大河注东溟。","遂为西峙岳，雄雄镇秦京。","大君包覆载，至德被群生。","上帝伫昭告，金天思奉迎。","人祇望幸久，何独禅云亭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f0ba8b57-e9a2-4df2-8aa4-30c4dca0420c","tags":["华山"]},{"id":"poem-12484619549da6c67427462f","title":"游蒋山题辛夷花寄陈奉礼本约陈同游不至","author":"徐铉","dynasty":"宋","verses":["今岁游山已恨迟，山中仍喜见辛夷。","簪缨且免全为累，桃李犹堪别作期。","晴后日高偏照灼，晚来风急渐离披。","山郎不作同行伴，折是何由寄所思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-088f6f69-4ad2-4b2a-bb84-a34535ce984a","tags":[]},{"id":"poem-125ee3552b4e7ef2d190aca0","title":"酒泉子·秋月婵娟","author":"李珣","dynasty":"五代","verses":["秋月婵娟，皎洁碧纱窗外。","照花穿竹冷沉沉，印池心。","凝露滴，砌蛩吟，惊觉谢娘残梦。","夜深斜傍枕前来，影徘徊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-40","tags":[]},{"id":"poem-125f6aac8b0ff5eae115c5fc","title":"寄叶勤次其韵","author":"刘跂","dynasty":"宋","verses":["五斗折腰俱为贫，诗书律令若为分。","西山今朝有爽气，北阙无时飞白云。","一纸绸缪三岁字，七言憀栗九章文。","故人好在长相忆，怅望江皋麋鹿群。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-bd702548-a480-47ef-9ed8-b48bd855ef3d","tags":[]},{"id":"poem-1260b538ea64fc3aa134eb3f","title":"伏虎岭残雪","author":"赵文","dynasty":"宋","verses":["晴得一霜晴更稳，饱饭不怕伏虎岭。","山高积雪冻犹在，昨日空惊雪画本。","日烘高树玉槎牙，时有冰花堕无影。","纷纷垂丝白海棠，得冷时能略苏醒。","可怪此君大曲折，向人雅拜欲求拯。","拥袍公子亦吟雪，岂识山中有此景。","笪桥烛下写诗成，一尊独酌谁能省。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a6c3a1b3-a56c-4ae3-b1d4-07b805bc5d40","tags":[]},{"id":"poem-127f4c05d4d5d604ae9ca470","title":"水调歌头·屋下疏流水","author":"赵鼎","dynasty":"宋","verses":["屋下疏流水，屋上列青山。","先生跨鹤何处，窈窕白云间。","采药当年三径，只有长松绿竹，霜吹晚萧然。","举酒高台上，彷佛揖群仙。","转银汉，飞宝鉴，溢清寒。","金波万顷不动，人在玉壶宽。","我唱君须起舞，要把嫦娥留住，相送一杯残。","醉矣拂衣去，一笑渺人寰。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-953","tags":[]},{"id":"poem-128ad90e900faa6a162107e7","title":"隔帘听·咫尺凤衾鸳帐","author":"柳永","dynasty":"宋","verses":["咫尺凤衾鸳帐，欲去无因到。","虾须窣地重门悄。","认绣履频移，洞房杳杳。","强语笑。","逞如簧、再三轻巧。","梳妆早。","琵琶闲抱。","爱品相思调。","声声似把芳心告。","隔帘听，赢得断肠多少。","恁烦恼。","除非共伊知道。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-138","tags":[]},{"id":"poem-128bdd568986a44eb1065b86","title":"寄人二首 二","author":"崔道融","dynasty":"唐","verses":["澹澹长江水，悠悠远客情。","落花相与恨，到地一无声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e1c4b0ee-27e3-4a7d-a8c1-c300a80bb39d","tags":["长江"]},{"id":"poem-128e3c9c9b6b00e3f5dfc5cc","title":"采桑子·马湖来舞钗初赐","author":"黄庭坚","dynasty":"宋","verses":["马湖来舞钗初赐，笳鼓声繁。","贤将开关。","威竦西山八诏蛮。","南溪地逐名贤重，深锁群山。","燕喜公闲。","一斛明珠两小鬟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-720","tags":[]},{"id":"poem-128f150ec7df75171a09b223","title":"公子家二首 一","author":"李山甫","dynasty":"唐","verses":["曾是皇家几世侯，入云高第照神州。","柳遮门户横金锁，花拥弦歌咽画楼。","锦袖妒姬争巧笑，玉衔[骄]马索闲游。","麻衣酷献平生业，醉倚春风不点头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-aa0be53e-c35f-4bcf-9963-a1a2ce76fa94","tags":[]},{"id":"poem-12926ea0aced758897f7b34a","title":"烛影摇红·波影翻帘","author":"贺铸","dynasty":"宋","verses":["波影翻帘，泪痕凝蜡青山馆。","故人千里念佳期，襟佩如相款。","惆怅更长梦短。","但衾枕、馀芬剩暖。","半窗斜月，照人肠断，啼鸟不管。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-110","tags":[]},{"id":"poem-12a92a85b18f2382627785d1","title":"上冯使君五首 三","author":"贯休","dynasty":"唐","verses":["樵叟无忧苦，地仙亦何别。","茆屋岸花中，弄孙头似雪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-46d5cea9-c175-494c-bde5-ba17a6e19cae","tags":[]},{"id":"poem-12ad9913e6924761c6433358","title":"闲园即事寄暕公","author":"司空曙","dynasty":"唐","verses":["欲就东林寄一身，尚怜儿女未成人。","柴门客去残阳在，药圃虫喧秋雨频。","近水方同梅市隐，曝衣多笑阮家贫。","深山兰若何时到，羡与闲云作四邻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e2740c24-d6db-4562-81ff-be9f0bfe16e0","tags":[]},{"id":"poem-12af7171ba22028e10eb19af","title":"生查子·斜日下平川","author":"赵老","dynasty":"宋","verses":["斜日下平川，楼角销霞缕。","摆尽浊尘缨，画栋萦非雾。","平生许子穷，今到知音处。","约伴玉簪游，好梦从天付。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-283","tags":[]},{"id":"poem-12b4f672db9d282f9d332aab","title":"奉同颜使君真卿清风楼赋得洞庭歌送吴炼师归林屋洞","author":"皎然","dynasty":"唐","verses":["名山洞府到金庭，三十六洞称最灵。","不有古仙启其秘，今日安知灵宝经。","中山炼师栖白云，道成仙秩号元君。","三千甲子朝玉帝，世上如今名始闻。","吐纳青牙养肌发，花冠玉舃何高洁。","不闻天上来谪仙，自是人间授真诀。","吴兴太守道家流，仙师远放清风楼。","应将内景还飞去，且从分风当此留。","湖之山兮楼上见，山冥冥兮水悠悠。","世人不到君自到，缥缈仙都谁与俦。","黄鹤孤云天上物，物外飘然自天匹。","一别千年未可期，仙家不数人间日。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4f9eba2b-be41-4cb3-ad59-c90b2cdba294","tags":["洞庭湖"]},{"id":"poem-12bb1d43f822326f9a00a01b","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["奴只得，往庙前，借取大公些个典。","与奴做盘缠，又欲买些绢，妆些旧绵。","又恐春寒，衣衫不办。","办与衣衫，一路免得身寒。","(生)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2565","tags":[]},{"id":"poem-12c803e13428e53e21ed77aa","title":"答十娘射雉","author":"张𬸦","dynasty":"唐","verses":["心绪恰相当，谁能护短长。","一床无两好，半丑亦何妨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c6fad4cc-fc7e-4396-9636-16c04e66338e","tags":[]},{"id":"poem-12cd5e368387cfc909f7dd5f","title":"偈颂 七","author":"文偃","dynasty":"唐","verses":["玩古松高云不齐，鸿鸧鹤抱几年栖。","剖㲉同时殊有异，羽张腾汉碧霄低。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0afb8d28-8b6c-4362-a50f-cf215959d7ac","tags":[]},{"id":"poem-12d1883c409830338d56b645","title":"龙子祠农人享神","author":"王士元","dynasty":"宋","verses":["晋州之西，山曰藐姑，有泉源源流不潴。","疏为八道沟与渠，坐令瘠土成膏腴。","多黍多稌多麻蔬，沄沄万亩碁局如。","田家终岁惟勤劬，虽有干旱无忧虞。","割牲酾酒父老趋，坎坎击鼓吹笙竽。","报答龙神醉饱余，宛若泽国江乡居。","晋州之东民岂迂，耕种自亦为农夫。","年年汲井井欲枯，赤日炙背田不濡。","父子筋力疲辘轳，肩頳汗浃良区区。","老我见此空嗟吁。","谁把劳逸分两途，凶年且为宽赋租。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5e18f4c8-9d40-4568-9764-3a0d1554595a","tags":[]},{"id":"poem-12d6649f7be4e6e201416690","title":"斗黑麻","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["自古姻缘事，非偶然，五百年前，赤绳系牵。","儿今去，听教言：我的儿，你到王门做媳妇，勿慢勿骄，必钦必敬。","孝顺姑嫜，数问寒暄。","［合］灯前泪涟，生离各一天。","他有日归宁，吾心始安。","我儿上轿去罢。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8095","tags":[]},{"id":"poem-12e23006b19d1cdc34ac5fbf","title":"哭翰林丁侍郎","author":"刘得仁","dynasty":"唐","verses":["相知出肺腑，非旧亦非亲。","每见云霄侣，多阳鄙拙身。","即期扶泰运，岂料哭贤人。","应是随先帝，依前作近臣。","平生任公直，爱弟尚风尘。","宅闭青松古，坟临赤水新。","官清仍齿壮，儿小复家贫。","惆怅天难问，空流泪满巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-7b0c00e0-5f71-46a7-8733-8b1abed9354f","tags":[]},{"id":"poem-12e2b49edf7e46cdeacac264","title":"甘州遍·秋风紧","author":"毛文锡","dynasty":"五代","verses":["秋风紧，平碛雁行低，阵云齐。","萧萧飒飒，边声四起，愁闻戍角与征鼙。","青冢北，黑山西。","沙飞聚散无定，往往路人迷。","铁衣冷，战马血沾蹄，破番奚。","凤凰诏下，步步蹑丹梯。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-14","tags":[]},{"id":"poem-12e6d8ec424cf3810c04ae79","title":"近闻","author":"杜甫","dynasty":"唐","verses":["近闻犬戎远遁逃，牧马不敢侵临洮。","渭水逶迤白日净，陇山萧瑟秋云高。","崆峒五原亦无事，北庭数有关中使。","似闻赞普更求亲，舅甥和好应难弃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d9e237c6-27c4-46c7-a998-d5c3bd12426b","tags":[]},{"id":"poem-12e80733c0ee5bb5ce74a429","title":"云汉","author":"佚名","dynasty":"先秦","verses":["倬彼云汉，昭回于天。王曰：于乎！何辜今之人？天降丧乱，饥馑荐臻。","靡神不举，靡爱斯牲。圭壁既卒，宁莫我听？","旱既大甚，蕴隆虫虫。不殄禋祀，自郊徂宫。上下奠瘗，靡神不宗。","后稷不克，上帝不临。耗斁下土，宁丁我梗。","旱既大甚，则不可推。兢兢业业，如霆如雷。周余黎民，靡有孑遗。","昊天上帝，则不我遗。胡不相畏？先祖于摧。","旱既大甚，则不可沮。赫赫炎炎，云我无所。大命近止，靡瞻靡顾。","群公先正，则不我助。父母先祖，胡宁忍予？","旱既大甚，涤涤山川。旱魃为虐，如惔如焚。我心惮暑，忧心如熏。","群公先正，则不我闻。昊天上帝，宁俾我遁？","旱既大甚，黾勉畏去。胡宁瘨我以旱？憯不知其故。祈年孔夙，方社不莫。","昊天上帝，则不我虞。","敬恭明神，宜无悔怒。旱既大甚，散无友纪。鞫哉庶正，疚哉冢宰。","趣马师氏，膳夫左右。靡人不周。无不能止，瞻卬昊天，云如何里！","瞻卬昊天，有嘒其星。大夫君子，昭假无赢。大命近止，无弃尔成。","何求为我。以戾庶正。瞻卬昊天，曷惠其宁？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-257","tags":[]},{"id":"poem-12e878f02b7b7c2b452ab2ca","title":"玉楼春·玉烛光明正旦好","author":"杜安世","dynasty":"宋","verses":["玉烛光明正旦好。","斗柄东回春太早。","岭寒犹锁去年梅，江暖新催今岁草。","蜀国熙熙冬令杪。","更喜寿阳新梦觉。","玉杯齐举乐音谐，遥想金阶天仗晓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-889","tags":[]},{"id":"poem-12f0239dcec70e9f3ac87d4d","title":"如梦令·红杏白梨肌理","author":"史浩","dynasty":"宋","verses":["红杏白梨肌理。","时样新妆淡伫。","真个是观音，少个杨枝净水。","欢喜。","欢喜。","尽此一锺醇美。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-169","tags":[]},{"id":"poem-12f363be2c7ffe8992e536d8","title":"奉和幸安乐公主山庄应制","author":"萧至忠","dynasty":"唐","verses":["西郊窈窕凤皇台，北渚平明法驾来。","匝地金声初度曲，周堂玉溜好传杯。","湾路分游画舟转，岸门相向碧亭开。","微臣此时承宴乐，髣髴疑从星汉回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-71c0f59c-3b6b-4083-9250-e0d99ea57f0f","tags":[]},{"id":"poem-1300ab7a1e6fabde67180673","title":"鹧鸪天·舞凤飞龙五百年","author":"张孝祥","dynasty":"宋","verses":["舞凤飞龙五百年。","尽将锦绣裹山川。","王家券册诸孙嗣，主第笙歌故国传。","居玉铉，拥金蝉。","祗今门户庆蝉联。","君侯合侍明光殿，且作横槎海上仙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-237","tags":[]},{"id":"poem-13045aecf2268a9d87803d6d","title":"下终南山过斛斯山人宿置酒","author":"李白","dynasty":"唐","verses":["暮从碧山下，山月随人归。","却顾所来径，苍苍横翠微。","相携及田家，童稚开荆扉。","绿竹入幽径，青萝拂行衣。","欢言得所憩，美酒聊共挥。","长歌吟松风，曲尽河星稀。","我醉君复乐，陶然共忘机。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ca4cc6b3-a324-48c0-89c0-bb36c09c4930","tags":["唐诗三百首","终南山","五言古诗","田园","写景","饮酒"]},{"id":"poem-1304bb028bf4ecbd72700c0e","title":"题方公院寄夏侯明府","author":"贯休","dynasty":"唐","verses":["银地有余光，方公道益芳。","谁分修藏力，顶有剃头霜。","经勘松风燥，簷垂坞茗香。","终须结西社，此县似柴桑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-522876a2-be3b-4275-a0ea-b3238c20e796","tags":[]},{"id":"poem-1306c54ef8ccd97f1f5c7ce6","title":"巴山道中除夜书怀","author":"崔涂","dynasty":"唐","verses":["迢遰三巴路，羇危万里身。","乱山残雪夜，孤烛异乡春。","渐与骨肉远，转于僮仆亲。","那堪正漂泊，明日岁华新。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9d33c118-cde9-49af-b572-c43427a10b48","tags":["羁旅","唐诗三百首","五言律诗","春节","思乡"]},{"id":"poem-1308fa73d18583afcdb527bf","title":"送李校书赴东川幕","author":"卢纶","dynasty":"唐","verses":["泥坂望青城，浮云与栈平。","字形知国号，眉势识山名。","编简尘封阁，戈鋋雪照营。","男儿须聘用，莫信笔堪耕。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-dd4b60d2-ed07-456f-bb82-2db027e705ed","tags":[]},{"id":"poem-1312e299760c4eb5832395aa","title":"宿定陵寺","author":"卢纶","dynasty":"唐","verses":["古塔荒台出禁墙，磬声初尽漏声长。","云生紫殿幡花湿，月照青山松栢香。","禅室夜闻风过竹，奠筵朝启露沾裳。","谁悟威灵同寂灭，更堪砧杵发昭阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-37d82fab-d24d-41ee-9547-b828eec2e945","tags":[]},{"id":"poem-1312e4b322c822c2fbe6f156","title":"伴读书","author":"杨景贤","dynasty":"元","verses":["我、我、我，使金枪法力强，恁、恁、恁，持宝杵威风壮。","众神祗齐保护他无恙，恁、恁离了上方。","他、他，往了西方，俺程程保护他消灾障。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10124","tags":[]},{"id":"poem-131412df9d887b1d6a3a1658","title":"哥舒歌","author":"西鄙人","dynasty":"唐","verses":["北斗七星高，哥舒夜带刀。","至今窥牧马，不敢过临洮。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ac2ec0ba-10b1-4ae3-8859-1e7752625331","tags":["唐诗三百首","赞颂","五言绝句","民歌"]},{"id":"poem-1317797655d3f1b0454e5925","title":"赠制香蜡茶者","author":"释居简","dynasty":"宋","verses":["玄质团团玉不如，翠钿小切试昆吾。","文园病酒文君老，盍荐芳甘瀹道腴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-5319edc0-383f-4f04-b2b6-ff2d2cb55cb8","tags":[]},{"id":"poem-1319ac098329ad579fdbc6df","title":"依韵奉和司徒侍中龙兴灯夕","author":"史卫卿","dynasty":"宋","verses":["宝炬燃红映百坊，佛灯相照有余光。","樽前尽被公孙礼，席上惟无处士狂。","午夜笙歌欢是伯，几家帘幕醉成乡。","都人犹怕春宵短，共乐何妨舞袖长。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-6a776a92-7ab3-4ce0-a812-e07ad6dcb95c","tags":[]},{"id":"poem-1319e09913b446f02ff3e59a","title":"郊庙歌辞 封泰山乐章 舒和","author":"张说","dynasty":"唐","verses":["六钟翕协六变成，八佾倘佯八风生。","乐九[韶]兮人神感，美七德兮天地清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-edf071ea-ed26-4840-8842-fab95743a231","tags":["泰山"]},{"id":"poem-1323ae1b233b39ff59c25861","title":"望远行·春日迟迟思寂寥","author":"李珣","dynasty":"五代","verses":["春日迟迟思寂寥，行客关山路遥。","琼窗时听语莺娇，柳丝牵恨一条条。","休晕绣，罢吹萧，貌逐残花暗凋。","同心犹结旧裙腰，忍辜风月度良宵。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-41","tags":[]},{"id":"poem-1328dc3da3a5fb4c654fca5d","title":"浣溪沙·云峡风高叶乱飞","author":"顾敻","dynasty":"五代","verses":["云峡风高叶乱飞，小庭寒雨绿苔微，深闺人静掩屏帷。","粉黛暗愁金带枕，鸳鸯空绕画罗衣，那堪辜负不思归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-5","tags":[]},{"id":"poem-132bde5a1bc0de150f26e784","title":"织女怀牵牛","author":"曹唐","dynasty":"唐","verses":["北斗佳人双泪流，眼穿肠断为牵牛。","封题锦字凝新恨，抛掷金梭织旧愁。","桂树三春烟漠漠，银河一水夜悠悠。","欲将心向仙郎说，借问榆花早晚秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9997089f-74db-4739-9d9a-8e632fc48490","tags":[]},{"id":"poem-132da5b0188288e123f0f9af","title":"送鄂州崔大夫赴镇","author":"刘得仁","dynasty":"唐","verses":["廉问帝难人，朝庭辍重臣。","入山初有雪，登路正无尘。","去国鸣驺缓，经云住斾频。","千峰与万木，清听雨情新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9c28c1bb-a4bd-47ef-9b8b-948384c0d164","tags":[]},{"id":"poem-13379f397fee90ebbbf1cbf7","title":"文献太子挽歌辞五首  其五","author":"徐铉","dynasty":"宋","verses":["彩仗清晨出，非同齿胄时。","愁烟锁平甸，朔吹绕寒枝。","楚客来何补，缑山去莫追。","回瞻飞盖处，掩袂不胜悲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-96a1439e-1efb-4415-b8ab-289a4db677ab","tags":[]},{"id":"poem-1343bc27f99a77f1f548a94d","title":"山花子·银字笙寒调正长","author":"和凝","dynasty":"五代","verses":["银字笙寒调正长，水纹簟冷画屏凉。","玉腕重金扼臂，淡梳妆。","几度试香纤手暖，一回尝酒绛唇光。","佯弄红丝蝇拂子，打檀郎。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-19","tags":[]},{"id":"poem-1351bea541009337da6c27b6","title":"沈千运旧居","author":"张籍","dynasty":"唐","verses":["汝北君子宅，我来见颓墉。","乱离子孙尽，地属邻里翁。","土木被丘墟，谿路不连通。","旧井蔓草合，牛羊坠其中。","君辞天下书，放意任体躬。","一生不自力，家与逆旅同。","高议切星辰，余声激瘖聋。","方将旌旧闾，百世可封崇。","嗟其未积年，已为荒林丛。","时岂无知音，不能崇此风。","浩荡竟无覩，我将安所从。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c490a58a-f973-4f3b-842c-472aeb3f660e","tags":[]},{"id":"poem-1354a1bb2ef00dc03afed5f8","title":"感庭秋・撼庭秋·红笺封了还重拆","author":"欧阳修","dynasty":"宋","verses":["红笺封了还重拆。","这添追忆。","且教伊见我，别来翠减香销端的。","渌波平远，暮山重叠，算难凭鳞翼。","倚危楼极目，无情细草长天色。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-803","tags":[]},{"id":"poem-1365fc6f3ff90a97542ff1ec","title":"和剡宰二首  其一","author":"曾协","dynasty":"宋","verses":["绿阴匼匝欲周阿，正午庭空雀可罗。","更许瘦筇支病骨，玉山影里听弦歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-417a662f-e807-4096-b6f0-86de3f8fcd95","tags":[]},{"id":"poem-1373604aacda2b750c54c5fb","title":"谷风","author":"佚名","dynasty":"先秦","verses":["习习谷风，维风及雨。将恐将惧，维予与女。将安将乐，女转弃予。","习习谷风，维风及颓。将恐将惧，置予于怀。将安将乐，弃予如遗。","习习谷风，维山崔嵬。无草不死，无木不萎。忘我大德，思我小怨。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-200","tags":[]},{"id":"poem-1373af4dc1ba7ede69d278fc","title":"别张十三建封","author":"杜甫","dynasty":"唐","verses":["尝读唐实录，国家草昧初。","刘裴建首义，龙见尚踌躇。","秦王拨乱姿，一劒总兵符。","汾晋为丰沛，暴隋竟涤除。","宗臣则庙食，后祀何疎芜。","彭城英雄种，宜膺将相图。","尔惟外曾孙，倜傥汗血驹。","眼中万少年，用意尽崎岖。","相逢长沙亭，乍问绪业余。","乃吾故人子，童丱聊居诸。","挥手洒衰泪，仰看八尺躯。","内外名家流，风神荡江湖。","范云堪晚友，嵇绍自不孤。","择材征南幕，湖落回鲸鱼。","载感贾生恸，复闻乐毅书。","主忧急盗贼，师老荒京都。","旧丘岂税驾，大厦倾宜扶。","君臣各有分，管葛本时须。","虽当霰雪严，未觉栝柏枯。","高义在云台，嘶鸣望天衢。","羽人埽碧海，功业竟何如。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b4af6fc2-0752-4841-88c1-30a208a020a1","tags":[]},{"id":"poem-1378fdf94edaa2337b7ebacb","title":"题花钿","author":"卢承丘","dynasty":"唐","verses":["傅粉销金翦翠霞，黛烟浓处添铅华。","也知曾伴姮娥笑，将来村里卖谁家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-454fcc52-8720-4211-a443-d473c588e641","tags":[]},{"id":"poem-13831ae527fc65da7e739534","title":"渔父·白芷汀寒立鹭鸶","author":"和凝","dynasty":"五代","verses":["白芷汀寒立鹭鸶，苹风轻剪浪花时。","烟幂幂，日迟迟。","香引芙蓉惹钓丝。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-32","tags":[]},{"id":"poem-138f5ff34972a75c64861e2a","title":"玉楼春·玉琴虚下伤心泪","author":"周邦彦","dynasty":"宋","verses":["玉琴虚下伤心泪。","只有文君知曲意。","帘烘楼迥月宜人，酒暖香融春有味。","萋萋芳草迷千里。","惆怅王孙行未已。","天涯回首一销魂，二十四桥歌舞地。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-448","tags":[]},{"id":"poem-13959540a5aa74c33dcd09ca","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(小生)叹一身钱无半文，无相识有谁是亲？(生)你说书内有黄金，何不看书，度日营生？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1717","tags":[]},{"id":"poem-13962b0d29b3be5b39b5b05a","title":"醉花阴·薄雾浓云愁永昼","author":"李清照","dynasty":"宋","verses":["薄雾浓云愁永昼。","瑞脑消金兽。","佳节又重阳，玉枕纱厨，半夜凉初透。","东篱把洒黄昏后，有暗香盈袖。","莫道不消魂，帘卷西风，人似黄花瘦。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-201","tags":["宋词三百首"]},{"id":"poem-13985861f6ae0f37708ec853","title":"自愧","author":"李咸用","dynasty":"唐","verses":["多负悬弧礼，危时隐薜萝。","有心明俎豆，无力执干戈。","壮士难移节，贞松不改柯。","缨尘徒自满，欲濯待清波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-dfe9b161-4cdc-4cb3-99a7-f250a07afe10","tags":[]},{"id":"poem-13ab5fe77fc53317083ccf38","title":"怀王龟龄","author":"姜大吕","dynasty":"宋","verses":["左原消息杳无闻，令我愁怀似乱云。","多病废诗兼废酒，青春孤我亦孤君。","要同学问文章乐，无奈东西南北分。","况是一簷残雨后，落花飞絮两纷纷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-3d911d44-d459-4199-b395-6ffffb52fccf","tags":[]},{"id":"poem-13aed2d8833c1af174e3cc5f","title":"颂古七十六首  其四三","author":"释士珪","dynasty":"宋","verses":["雷火光中休草草，剑轮锋上莫忉忉。","等闲放却全身入，终不当头犯一毫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-7b898a6d-edc3-47a1-b9de-782526e3cb9b","tags":[]},{"id":"poem-13b7fe20bc17af4a1fb7b88a","title":"红窗月·燕归花谢","author":"纳兰性德","dynasty":"清","verses":["燕归花谢，早因循、又过清明。","是一般风景，两样心情。","犹记碧桃影里、誓三生。","乌丝阑纸娇红篆，历历春星。","道休孤密约，鉴取深盟。","语罢一丝香露、湿银屏。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-143","tags":[]},{"id":"poem-13bdc49c7a2699e3caf5cf53","title":"秀才石君予同年子也携书见投重之以歌诗意甚勤厚其归也邀予言为赠因作五言以勉之","author":"苏颂","dynasty":"宋","verses":["石生故人子，袖书远相过。","趋翔有父风，步阔冠峨峨。","自言少也孤，奉亲由江鄱。","区区营甘旨，靡暇谋其他。","三十未有成，无门托丝萝。","求知走四方，慷慨成悲歌。","顾我旧朝采，谓能激余波。","多惭僻郡守，局趣如生何。","空持赠我句，坐合长吟哦。","方今绍唐虞，咏歌继卷阿。","举世用经术，革去辞章讹。","诏书起遗逸，草泽咸搜罗。","高爵待俊杰，世砺钝以磨。","君子务藏器，生其勤切磋。","乘时挟才策，继世收贤科。","壮怀无自忽，流年易蹉跎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-bebeea4b-f7ff-4cd6-9537-dc1d90d149be","tags":[]},{"id":"poem-13c1ce7b8cdd8ca8aaaf64c0","title":"十诗谢廖计使  其一","author":"陈造","dynasty":"宋","verses":["二年仕穷山，书外睡作魔。","吹律黍为茁，頼公有孰何。","悬知登门初，大宅浮阳和。","泛爱公自尔，小子何足多。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-0ec0535b-741b-4c52-8dfd-7c922a49d4d4","tags":[]},{"id":"poem-13c8097e719a4f54318a98a1","title":"六次韵","author":"王十朋","dynasty":"宋","verses":["年少题诗入杏园，横空硬语胜郊盘。","新吟陈紫并江绿，深逼蕉黄与荔丹。","官舍聊淹广文冷，雁行高并玉峰寒。","黄堂病守相将去，秋菊落英谁共餐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-fe11dc27-e413-4f87-aa2a-a499b312a733","tags":[]},{"id":"poem-13ca3dca325b8bd7fe5aba8c","title":"华顶","author":"李绅","dynasty":"唐","verses":["欲向仙峰炼九丹，独瞻华顶礼仙坛。","石标琪树凌空碧，水挂银河映月寒。","天外鹤声随绛节，洞中云气隐琅玕。","浮生未有从师地，空诵仙经想羽翰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fa117c57-cc2f-4647-a501-59a4d5b7065a","tags":[]}];
